/* stopwatch: the course data of the module's test and of its own course (ci/oncourse.js).
 *
 * Basic-Pharmacokinetics' own data, read from a read-only copy at ac2eb73, with nothing
 * written for the test:
 *   exam        src/course.js `exams`, the entry with id 3 ("Exam 3 (final)", the course's
 *               `activeExam`), every field as the course has it. It has no `typed`: the
 *               course's own engine draws calculations onto every paper (src/shell.html
 *               line 1180, src/views.js lines 3270-3277), and the kit core does that only for an
 *               exam with `typed: true`. So on this exam's papers the kit draws only
 *               single-answer and select-all questions.
 *   activeExam  src/course.js `activeExam` (3)
 *   calc        the 5 numeric questions of the professor's Canvas Quiz 4 (src/q13_quizzes.js:
 *               cq4-2, cq4-4, cq4-6, cq4-8, cq4-9), the quiz whose `said` line in src/course.js (line 264) gives
 *               the pace: "A few calculations, each meant to take 2 minutes or less"
 *   qs          those 5 and 55 single-answer and select-all questions that fill Exam 3's
 *               four pools (src/q*.js), every field as the course has it
 *   topics      the 10 TOPICS entries those questions name
 *   lectures    the 9 COURSE.lectures entries whose deck those questions' cites name
 *   skills      the COURSE.skills entries those questions use
 *   images      the 7 src/images.json entries those questions show
 * Which questions (the rule only chooses; no question is changed): a question is taken when
 * it is not lowYield, does not name the professor anywhere in its text, passes the kit
 * core's rules for a question (style_check.js STEM_RE, no figure promised by the stem,
 * a cite that names a lecture deck, the option and step rules of test.js, no word
 * "undefined", "null" or "NaN") and its dupOf chain can be taken too. For each pool of
 * Exam 3, questions without an image come first, in the course's order, then questions
 * with an image, smallest image first, until the pool holds its marks plus one question
 * family and its share of select-all questions plus one. The script that made this file
 * is kept with the review evidence (branch evidence/stopwatch, scripts/mkfixture.js).
 * The one change to the data: `prof` is left out here, and courseData(prof) writes the
 * course's own first professor (the kit template's "Professor") into every question,
 * topic and lecture, so the kit holds no personal name.
 * Placement in a course (not a change to what the data says): every question, topic,
 * subtopic and lecture id, and each reference to one (dupOf, topic, sub, lecture), carries
 * the prefix sw- with the course's id kept inside it (cq4-2 -> sw-cq4-2, topic multi ->
 * sw-multi, subtopic multi/ssbolus -> sw-multi/sw-ssbolus, lecture L07 -> sw-L07), so these
 * never meet another module's copy of the same Basic-Pharmacokinetics data in one course
 * (kit rule 2, /tmp/port-tools/CIDATA.md); the topics come after the course's own;
 * COURSE.exams becomes this one exam.
 * Data that names other modules' data (kit rule 4): a calculation's `setup` line names
 * plan-the-problem equations (EQUATIONS ids) and its `asks` names an ASKS key. courseData()
 * writes a `setup` only when the course's EQUATIONS has its `eq` (or it is "none") and every
 * `pre`, and an `asks` only when the course's ASKS has that key; otherwise the field is left
 * out (the module does not read either) and `left` says how many were left out.
 * courseData(prof) returns the question file (one question per line, opening {id:'...', in
 * the kit's question-file form, which core browser_test.js counts) and the course.js line.
 */
const FIX = {"source":"Basic-Pharmacokinetics ac2eb73","exam":{"id":3,"name":"Exam 3 (final)","date":"2026-10-27","when":"2026-10-27T08:00","questions":40,"minutes":120,"sata":4,"blurb":"Tue 27 October, 8:00 a.m. Cumulative: 40 questions, 20 multiple choice and 20 fill in the blank, with 25% on the two lectures after Exam 2, PK-PD (12 Oct) and nonlinear pharmacokinetics (14 Oct). Know total clearance, ideal body weight and Cockcroft-Gault without the equation sheet. How the other 30 questions divide between Exam 1 and Exam 2 material is not published; this drill splits them evenly.","facts":[["When","Tue 27 October, starting at 8:00 a.m. (her announcement of 26 October)"],["After it","Exam review: Thu 29 October, 8:15 to 8:45 a.m., in the P2 classroom"],["Not on the sheet","Total clearance, ideal body weight and Cockcroft-Gault: \"we're only gonna use the ideal body weight\""],["What she expects","Zero and first order; k, t½, VD and Cp; total, renal and hepatic clearance; steady-state peaks, troughs, averages and tmax; Cp against time for each route; bioavailability; linear and nonlinear; AUC; duration of action and the times to steady state, to the peak and to elimination; Cp after IV bolus, IV infusion and extravascular doses"],["Weight","33% of the course grade"],["Shape","40 questions, \"similar in format to the two previous exams\": 20 multiple choice and 20 fill in the blank"],["New material","25%, 10 of the 40 questions, \"material that you have not been tested on before\": PK-PD (12 Oct) and nonlinear pharmacokinetics (14 Oct). On 14 Oct: \"25% new stuff, but the new isn't even really new\""],["The rest","Cumulative: Modules 1 to 7a. The split between Exam 1 and Exam 2 material is not published; this drill uses 15 and 15"]],"pools":[{"key":"f-e1","name":"Exam 1 material (Modules 1–3)","marks":15,"filter":{"exam":1}},{"key":"f-e2","name":"Exam 2 material (Modules 4–7a)","marks":15,"filter":{"exam":2}},{"key":"f-pkpd","name":"Module 7b — PK-PD relationship","marks":5,"filter":{"module":9}},{"key":"f-nl","name":"Module 8 — Nonlinear pharmacokinetics","marks":5,"filter":{"module":8}}]},"activeExam":3,"calc":["cq4-2","cq4-4","cq4-6","cq4-8","cq4-9"],"qs":[{"id":"m1-int-01","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"intro","sub":"disc","concept":"biopharmaceutics-defn","skill":"recall","source":"both","stem":"Which term covers the interrelationship of the physicochemical properties of a drug, the dosage form in which it is given, and the route of administration on the rate and extent of systemic drug absorption?","options":[{"t":"Biopharmaceutics","correct":true,"why":"This is her definition of biopharmaceutics: drug properties, dosage form and route, acting on the rate and extent of systemic absorption. Biopharmaceutics stops where the drug enters the circulation, which is where pharmacokinetics starts."},{"t":"Toxicology","correct":false,"why":"Clinical toxicology studies the adverse effects of drugs in the body: what a drug does once present, not how much gets in. Choosing it usually comes from reading \"extent\" as extent of injury rather than extent of absorption."},{"t":"Pharmacodynamics","correct":false,"why":"Choosing this confuses absorption with response. Pharmacodynamics relates drug concentration at the site of action to pharmacological response, so its two variables are concentration and effect. The definition names dosage form and route, which are formulation variables, and never a response."},{"t":"Pharmacology","correct":false,"why":"Pharmacology is the broader study of drug action, and picking it means answering at the level of the whole field rather than the specific discipline named. The definition is narrow and formulation-centred, so a general term cannot be the best match."}],"teach":[{"h":"The idea","list":["Each related discipline is defined by the two quantities it links.","Biopharmaceutics links the drug, the dosage form and the route to the rate and extent of absorption; drug-product design factors such as particle size and excipients fall within it.","Pharmacokinetics links concentration to time; pharmacodynamics links concentration to response.","Clinical toxicology deals with the adverse effects of drugs.","Rate of absorption shows in how early and how high the curve peaks (tmax and Cmax); extent is how much arrives, measured by the area under the curve (AUC)."]},{"h":"Where to read more","t":"Introduction.pdf, slide \"Related Discipline: Biopharmaceutics\"."}],"teachImg":"slide_Introduction_p6","cite":"Introduction.pdf slide 6, and the poll slide following slide 10","quote":"The interrelationship of the physicochemical drug properties, dosage form and route of administration on the rate and extent of systemic drug absorption"},{"id":"m1-ord-c01","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"zero","concept":"zero-order-defn","skill":"recall","source":"slide","stem":"In a zero-order reaction, the amount or concentration of drug decreases:","options":[{"t":"At a constant rate","correct":true,"why":"The differential form is {{frac:dC|dt}} = −k with no concentration term on the right, so the rate does not depend on how much drug is present. The same quantity leaves in each unit of time whether the concentration is high or low; integrating gives the straight line C = C0 − kt."},{"t":"At a rate proportional to the amount remaining","correct":false,"why":"That statement is the definition of a first-order reaction, where {{frac:dC|dt}} = −kC and the concentration appears on the right-hand side. The two definitions differ by exactly that one term. Selecting this means matching on the word rate without checking what the rate is tied to."},{"t":"By a constant fraction of the amount remaining per unit time","correct":false,"why":"A constant fraction per unit time is the first-order behaviour restated in words rather than symbols. For a zero-order process the fraction lost per hour grows as the concentration falls, because the quantity removed stays fixed while the amount present shrinks. Fraction and quantity are what separate the two orders."},{"t":"At a rate proportional to the square of the amount remaining","correct":false,"why":"A rate proportional to concentration squared would be second order, which is two steps away from the definition asked for. The exponent on the concentration term is what names the order, and zero order means that exponent is zero, so the term disappears entirely."}],"teach":[{"h":"The idea","list":["The order of a reaction is the power to which the concentration is raised in the rate law.","Zero order: the power is zero, so the concentration drops out: {{frac:dC|dt}} = −k, which integrates to C = C0 − kt.","C0 is the concentration at time zero; k carries units of concentration or amount per unit time.","On linear axes the line has slope −k; k itself is written as a positive number, the size of the loss per unit time.","Half-life: t½ = {{frac:C0|2k}}, so it changes with the starting concentration."]},{"h":"Where to read more","t":"Introduction.pdf, slide 17."}],"teachImg":"slide_Introduction_p20","cite":"Introduction.pdf slide 17","quote":"Amount or concentration of drug decreases at a constant rate"},{"id":"m1-ord-c03","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"first","concept":"first-order-properties","skill":"recall","source":"both","stem":"First-order processes are characterised by:","options":[{"t":"A constant half-life","correct":true,"why":"First-order half-life is 0.693 divided by the rate constant, and both are constants, so the half-life is constant and does not depend on the starting concentration. That is why a drug can be quoted with one half-life rather than a value for every dose."},{"t":"A constant rate of elimination","correct":false,"why":"Picking this holds on to the word constant and loses what it attaches to. The rate of elimination is the rate constant multiplied by the concentration, so it changes continuously as the concentration falls; a constant rate of elimination is the zero-order property."},{"t":"dC/dt = −k","correct":false,"why":"Choosing this treats the rate law as a shape to match rather than an equation to read for its concentration term. {{frac:dC|dt}} = −k has no concentration on the right-hand side, which makes it zero order. The first-order form is {{frac:dC|dt}} = −kC."},{"t":"Units of k of concentration or amount per unit time","correct":false,"why":"Choosing this gives the zero-order units. Concentration or amount per unit time are the units of a zero-order constant, which is itself a rate. A first-order constant multiplies a concentration to give a rate, so its units are reciprocal time."}],"teach":[{"h":"The idea","list":["Every first-order property follows from one fact: the rate is proportional to the concentration, {{frac:dC|dt}} = −kC.","The proportion removed per unit time is fixed, so the rate constant k has units of reciprocal time.","The half-life is fixed at {{frac:0.693|k}}; 0.693 is ln 2, because setting C = {{frac:C0|2}} in ln C = ln C0 − kt leaves k × t½ = ln 2.","The quantity removed per unit time is not fixed, so the rate of elimination falls as the concentration falls."]}],"teachImg":"slide_Introduction_p24","cite":"Introduction.pdf, poll slide following slide 21","quote":"first order processes, constant half-life, constant half-life, OK. The rate of elimination … the rate is constantly changing"},{"id":"m1-ord-c04","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"first","concept":"first-order-rate-depends","skill":"tell","source":"both","stem":"Which of the following best describes the rate of a first-order process?","options":[{"t":"It is proportional to the concentration of drug present","correct":true,"why":"The rate law {{frac:dC|dt}} = −kC puts the concentration on the right-hand side, so the rate cannot be independent of it: faster at high concentration, slower as it falls. What is independent of concentration is the rate constant, and so the half-life."},{"t":"It is independent of the concentration of drug present","why":"This swaps the rate constant for the rate. The constant is a fixed number in reciprocal time, but the rate is that constant times the concentration, so it changes whenever the concentration changes."},{"t":"It is constant over time","why":"Picking this reads the constant half-life of a first-order process as a constant rate. A rate that stays the same over time, the same quantity lost per unit time, is the zero-order case. In first order the rate is k times the concentration and falls with it; only k and the half-life stay fixed."},{"t":"It is set by the half-life alone","why":"This answer confuses the time to lose a fixed proportion with the quantity lost per unit time. A constant half-life is a real first-order property, but half of a large concentration is more drug than half of a small one over the same interval, so the rate changes while the half-life does not."}],"teach":[{"h":"The idea","list":["In a first-order process the rate and the rate constant behave differently as the concentration falls.","The rate constant k is fixed: the proportion of what is present that is removed per unit time.","The rate is k multiplied by the current concentration, so it is largest at the start and falls continuously.","A k of 0.04 hr⁻¹ removes the same fraction every hour, about 4% (1 − e^(−0.04) = 0.039), whatever the concentration.","In a zero-order process this reverses: the rate is fixed, and the proportion removed per unit time grows."]}],"teachImg":"slide_Introduction_p24","cite":"Introduction.pdf, poll slide following slide 21","quote":"the rate depends on the concentration that’s there"},{"id":"inf-c9","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"stop","concept":"post-cessation-model","skill":"recall","source":"both","stem":"Which of the following best describes the plasma concentration after a continuous intravenous infusion is stopped?","options":[{"t":"It declines by first-order elimination from the concentration at cessation","correct":true,"why":"With no input, only first-order elimination remains: the same decay seen after a bolus. The concentration at cessation plays the part of the initial concentration, and t is counted from cessation rather than from the start; getting that peak value right is the main work."},{"t":"It continues to rise toward the steady-state concentration","why":"Picking this reads a stopped infusion as one that is still running. The rise toward Css, the steady-state concentration, is driven by the input rate R; once R is zero nothing drives it, and only first-order elimination, with rate constant k, remains. The concentration can only fall from its value at cessation."},{"t":"It declines from the steady-state concentration in every case","why":"This answer treats every infusion as having reached its plateau before it stopped. The decline starts from Cpeak, the concentration at cessation, which equals Css only after about three to five half-lives of infusion; one stopped earlier decays from ({{frac:R|Cl}})(1 − e^(−kT)), where T is the infusion length and Cl clearance."},{"t":"It stays at the concentration reached at cessation","why":"Picking this reads the end of input as the end of all change. Elimination does not stop when the pump does: the first-order output, k times the amount in the body, continues whatever the input, so the concentration falls from the moment the infusion ends. A flat level would need input to keep matching output."}],"teach":[{"h":"The idea","list":["Stopping an infusion removes the zero-order input and leaves the first-order output unchanged.","From that point the curve is an ordinary first-order decay, C = Cpeak·e^(−kt), with t counted from cessation.","Cpeak, the concentration when the infusion stopped, is Css if the infusion ran to steady state, and ({{frac:R|Cl}})(1 − e^(−kT)) if it stopped earlier, T being the infusion length.","So every post-cessation problem has two steps: find Cpeak, then decay it for the stated time."]},{"h":"Where to read more","t":"3IntravenousInfusions.pdf, slide \"Drug Concentration after an IV Infusion has Ended\"."}],"cite":"3IntravenousInfusions.pdf, slide \"Drug Concentration after an IV Infusion has Ended\"","quote":"Think of that C peak as your C0 as your starting point."},{"id":"inf-c10","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"stop","concept":"peak-vs-css","skill":"tell","source":"both","stem":"Two patients receive the same drug at the same infusion rate. One infusion runs to steady state and the other is stopped after two half-lives. In calculating the concentration some hours after each infusion ends, how do the two differ?","options":[{"t":"The second decays from 75% of the plateau","correct":true,"why":"Two half-lives of infusion close three quarters of the gap to the plateau, so the concentration at cessation is 0.75 times Css rather than Css itself. That value is the starting point for the decay, and everything after it is identical between the two patients."},{"t":"The second decays with a larger rate constant","correct":false,"why":"The elimination rate constant belongs to the drug in the patient and does not depend on how long the infusion ran. Both curves fall at the same fractional rate once the infusion stops. Selecting this attributes a difference in starting height to a difference in slope."},{"t":"The second has a lower steady-state concentration","correct":false,"why":"Steady-state concentration is the infusion rate divided by clearance, and both patients have the same rate and the same drug, so both have the same Css. The second patient simply never got there. Confusing the plateau a regimen would reach with the level it actually reached is the specific error here."},{"t":"Both decay from the steady-state concentration","correct":false,"why":"This answer treats every post-infusion decay as starting from the plateau. Only an infusion run to steady state peaks at Css, the steady-state concentration; two half-lives of infusion leave the concentration at 0.75 Css, a quarter short. Starting the second decay from Css overestimates that patient at every later time, by the same factor throughout."}],"teach":[{"h":"The idea","list":["After cessation both patients follow the same first-order decay with the same k, so only the starting concentration can differ.","An infusion run to steady state starts its decay at Css (the steady-state concentration).","An infusion stopped earlier starts from Css × (1 − e^(−kT)), with T the duration actually infused.","Deciding which of the two applies is the first step in any post-cessation question."]}],"cite":"IV-Infusions-Practice-3---Solutions.pdf, parts f and g; 3IntravenousInfusions.pdf, slide \"Drug Concentration after an IV Infusion has Ended\"","quote":"Css or not Css"},{"id":"inf-c11","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"load","concept":"loading-purpose","skill":"recall","source":"both","stem":"What is the purpose of giving an intravenous loading dose at the start of a continuous infusion?","options":[{"t":"To reach the target steady-state concentration almost immediately","correct":true,"why":"Without a loading dose the concentration has to climb over three to five half-lives, which is unacceptable for a drug that is needed now. A bolus of the amount present at steady state reaches that level at once, and the infusion then holds it. The loading dose saves time; it does not raise the level."},{"t":"To raise the steady-state concentration above what the infusion alone would give","correct":false,"why":"The plateau is set by infusion rate and clearance, and a single bolus changes neither; the bolus is eliminated like the infused drug and adds nothing to the rate coming in. Choosing this treats the loading dose as extra drug that stays, when it only saves the time spent climbing to the plateau."},{"t":"To shorten the elimination half-life so that steady state arrives sooner","correct":false,"why":"Half-life is a property of the drug and the patient and no dose changes it. The loading dose does not make the approach to the plateau faster; it starts the patient at the plateau so that no approach is needed. Confusing those two is the reason this option is tempting."},{"t":"To allow a lower infusion rate to be used for the same effect","correct":false,"why":"The maintenance rate is fixed by the target concentration and the clearance; lowering it would let the level fall away from the target once the loading dose is eliminated. Picking this treats the total drug given, rather than the rate, as what matters."}],"teach":[{"h":"The idea","list":["A loading dose and an infusion rate answer two separate questions.","The rate sets where the concentration settles, because the plateau is the rate divided by clearance.","The loading dose sets how soon it gets there, by putting the steady-state amount into the body at once.","So DL (loading dose) = Css × VD, the steady-state concentration times the volume of distribution; equivalently {{frac:R|k}}, once R has been chosen for that target."]},{"h":"Where to read more","t":"3IntravenousInfusions.pdf, slide \"IV Bolus Loading Dose and Continuous IV Infusion\"."}],"cite":"3IntravenousInfusions.pdf, slide \"IV Bolus Loading Dose and Continuous IV Infusion\"","quote":"We want the loading dose to look like the amount of drug that’s in the body at steady state."},{"id":"inf-c12","tier":"new","exam":1,"module":3,"lecture":"L04","multi":true,"topic":"infusion","sub":"load","concept":"loading-dose-properties","skill":"apply","source":"both","stem":"Which of the following is true about a loading dose given at the same time as a continuous infusion is started? Select all that apply.","options":[{"t":"An appropriate loading dose can be calculated as R divided by k","correct":true,"why":"Infusion rate divided by elimination rate constant is the amount the infusion would eventually hold in the body at steady state. It is right provided the rate was chosen to hit the intended concentration; an arbitrary rate gives a loading dose matched to that arbitrary plateau instead of the target."},{"t":"An appropriate loading dose is Css multiplied by the volume of distribution","correct":true,"why":"Volume of distribution relates the amount in the body to the plasma concentration, so target concentration times volume gives the amount needed to produce that concentration. This route starts from the target rather than the rate, and it agrees with {{frac:R|k}} when the rate matches the target."},{"t":"The steady-state concentration is unchanged by the loading dose","correct":true,"why":"The plateau is the infusion rate divided by clearance, and a single bolus alters neither. The loading dose changes only the early part of the curve, and the bolus component decays away as the infusion component builds. Her practice problem asks for the steady-state concentration twice, with different loading doses, and the answer is unchanged."},{"t":"The loading dose shortens the elimination half-life","correct":false,"why":"Picking this reads the loading dose as something that acts on the drug rather than on the amount present. Half-life is 0.693 divided by k, the elimination rate constant, and k is a constant of the drug in the patient that no dose changes. A loading dose changes only how soon the target is reached."},{"t":"The loading dose must be recalculated whenever the half-life changes","correct":false,"why":"Choosing this confuses the loading dose with the maintenance rate. The loading dose fills the volume of distribution to the target, so it depends on Css and VD, not on clearance. In her renal failure example clearance and the maintenance rate fall, but the loading dose stays the same."}],"teach":[{"h":"The idea","list":["The loading dose brings the body to the target concentration; the infusion replaces what is eliminated.","DL = Css × VD, or {{frac:R|k}} when the rate already matches the target (Css the steady-state concentration, VD the volume of distribution, R the infusion rate, k the elimination rate constant).","The plateau depends on rate and clearance, so the loading dose does not alter it."]}],"cite":"3IntravenousInfusions.pdf, slide \"IV Bolus Loading Dose and Continuous IV Infusion\"; IV-Infusions-Practice-4-Solutions.pdf part g","quote":"another way to think about this loading dose. Concentration of drug in the body at steady-state times the volume and distribution"},{"id":"inf-c13","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"load","concept":"loading-dose-mismatch","skill":"apply","source":"transcript","stem":"A drug is infused at a rate that gives a steady-state concentration of 24 mg/L, and the loading dose given with it is larger than the amount of drug the body holds at steady state. What does the concentration-time curve look like?","options":[{"t":"It starts above 24 mg/L and falls toward it","correct":true,"why":"The concentration is the decaying bolus curve plus the rising infusion curve; too much drug at once puts the sum above the plateau early, and it falls back as the bolus decays. With her 288 mg loading dose the two-hour concentration is 24 mg/L; 388 mg puts it near 30 mg/L, above the plateau."},{"t":"It starts below 24 mg/L and climbs to it","correct":false,"why":"That is the picture for a loading dose that is too small, where the bolus does not fill the volume of distribution to the target and the infusion has to make up the difference. Starting low is what a loading dose is given to avoid. Selecting this reverses the direction of the mismatch."},{"t":"It rises steadily to a plateau above 24 mg/L","correct":false,"why":"The plateau is the infusion rate divided by clearance and a bolus cannot move it, so no loading dose produces a higher final level. The excess from an oversized bolus is eliminated like any other drug. This answer lets the loading dose set the steady-state concentration."},{"t":"It stays flat at 24 mg/L from the first minute","correct":false,"why":"That is what an appropriate loading dose achieves, and the stem states this one is larger than the steady-state amount. A flat line is the sum of a decaying and a rising curve only when the bolus exactly fills the volume of distribution to Css. Choosing this ignores the condition set in the stem."}],"teach":[{"h":"The idea","list":["With a loading dose and an infusion together, the concentration at any moment is the sum of two curves: C = ({{frac:DL|VD}})e^(−kt) + ({{frac:R|Cl}})(1 − e^(−kt)).","The first term is a bolus decaying from the loading dose divided by the volume of distribution; the second is the infusion climbing toward Css (the steady-state concentration).","When the loading dose equals Css times the volume of distribution, the two sum to a flat line at Css.","Too much loading dose makes the early sum overshoot and fall back; too little makes it start low and climb."]}],"cite":"09-02 lecture (transcript); 3IntravenousInfusions.pdf, slide \"IV Bolus Loading Dose and Continuous IV Infusion\"","quote":"the loading dose helps us to reach that steady state concentration, like almost immediately. But you got to choose wisely on the loading dose","note":"In class she reworked the 288 mg example with a 388 mg loading dose: the level two hours in was about 30 mg/L, against a plateau of 24 mg/L.","audit":"The slide carries only a graph of the too-high and too-low cases with no printed caption, so the described behaviour is taken from the 09-02 transcript, where she recomputes her 288 mg example with 388 mg and gets about 30 mg/L at two hours against a plateau of 24 mg/L."},{"id":"inf-c16","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"basics","concept":"bolus-dose-dependence","skill":"apply","source":"slide","stem":"Which of the following would you expect to increase with an increase in an intravenous bolus dose?","options":[{"t":"Plasma drug concentration","correct":true,"why":"Concentration is the amount in the body divided by the volume of distribution, so in a fixed volume a larger dose gives a proportionally larger concentration. Doubling the dose doubles the initial concentration and leaves the shape of the curve unchanged."},{"t":"Clearance","correct":false,"why":"Clearance is the elimination rate constant times the volume of distribution, both constant for the drug in the patient. A larger dose means more drug removed per hour but the same volume of plasma cleared per hour; confusing the rate of elimination with clearance makes this look right."},{"t":"Elimination half-life","correct":false,"why":"Picking this reads a larger amount as taking proportionally longer to remove, which describes zero-order elimination. Half-life is 0.693 divided by k, the elimination rate constant, and neither term contains the dose. In first-order elimination, losing half takes the same time from a high or a low start; a bigger dose keeps the same half-life."},{"t":"Apparent volume of distribution","correct":false,"why":"Picking this treats volume of distribution as a container that stretches with the dose. It is a proportionality constant describing how the drug distributes between plasma and the rest of the body; it belongs to the drug, not the dose. Giving more drug fills the same apparent volume to a higher concentration."}],"teach":[{"h":"The idea","list":["In a linear first-order system the dose scales the concentrations and changes nothing else.","C0 = {{frac:D0|VD}}, so doubling the dose doubles C0 and every later concentration with it.","t½ = {{frac:0.693|k}} and Cl = k × VD contain no dose, so neither moves when the dose does; VD is a constant of the drug in that patient.","The amount eliminated per hour, Cl × Cp, does rise with the dose; the volume cleared per hour, Cl, does not."]},{"h":"How she tests it","t":"The opening poll of the infusion deck asks this question in these words."}],"cite":"3IntravenousInfusions.pdf, opening poll slide","quote":"Which of the following would you expect to increase with an increase in IV bolus dose?"},{"id":"m5-c06","tier":"new","exam":2,"module":5,"lecture":"L06","topic":"oral","sub":"extravasc","concept":"modified-release-input","skill":"apply","source":"transcript","stem":"A solid oral dosage form is formulated to release its drug at a constant rate. How is that product's input and output described?","options":[{"t":"Zero-order input with first-order output","correct":true,"why":"A constant release rate is a fixed amount per hour, which is zero order. Elimination does not depend on the product, so it stays first order. The result looks like an IV infusion: the level climbs and levels off rather than peaking."},{"t":"First-order input with first-order output","why":"This is the ordinary tablet, and choosing it misses what the product was built to change. Its release slows as less drug is left in it, which is what first order means. A constant-rate product is built so that release does not slow, which makes its input zero order."},{"t":"Zero-order input with zero-order output","why":"The input half is right and the output half is not. The product controls only release. Once drug is in the plasma the body removes a fixed fraction of it each hour, which is first order, whatever the tablet did."},{"t":"Instantaneous input with first-order output","why":"Instantaneous input is an IV bolus, where the whole dose enters at once. A product that releases drug steadily over hours is the opposite: its input is spread over time at a constant rate."}],"teach":[{"h":"The output is first order, whatever the product","list":["In this module elimination is first order: each hour the body removes a fixed fraction of the drug in it.","A formulation controls only how the drug is released, not how the body removes drug already in the plasma."]},{"h":"The input is set by how the drug is released","t":"IV means intravenous.","table":{"head":["How drug enters","Input","Example","Curve"],"rows":[["All at once","Instantaneous","IV bolus","Highest at time zero, then falls"],["A fixed fraction of what is left, each hour","First order","Ordinary tablet or capsule","Rises to a peak, then falls"],["A fixed amount each hour","Zero order","IV infusion; constant-rate release product","Levels off while release continues, then falls"]]},"fig":"input_types","after":"A constant-rate product releases the same amount each hour, however much is left in the tablet. That is a zero-order input."}],"cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Summary\"; 09.21 lecture","quote":"if we have a truly modified zero solid dosage form that is releasing drug at a zero order rate … Looks like IV infusion"},{"id":"m5-c07","tier":"new","exam":2,"module":5,"lecture":"L06","topic":"oral","sub":"conc","concept":"f-meaning","skill":"recall","source":"both","stem":"In the single oral dose equation, what does the factor F represent?","options":[{"t":"The fraction of the dose absorbed and available to the body","correct":true,"why":"Some of a swallowed dose never reaches the systemic circulation: it is not absorbed, or the liver removes it on the way through. F is the share of the dose that survives, so dose × F is what the body has to work with; for an intravenous dose F is taken as one."},{"t":"The fraction of the drug bound to plasma protein","correct":false,"why":"This reads F as a fraction of drug rather than of dose. The bound fraction describes drug already in the plasma; F decides how much got there, and because F multiplies the dose, raising it raises every concentration. No binding term appears in the single oral dose equation."},{"t":"The fraction of the dose excreted unchanged in the urine","correct":false,"why":"That fraction describes elimination and belongs in clearance calculations, not in the input term. If F were an excreted fraction, raising it would lower the plasma concentration, the opposite of how F behaves; the two are easy to swap because both are fractions of a dose."},{"t":"The fraction of the absorption rate constant contributed by dissolution","correct":false,"why":"There is no such split in this model; the whole absorption process is compressed into the single constant ka. F is a fraction of the dose and is not part of any rate. Reaching for this answer means trying to attach F to the neighbouring ka rather than to the dose."}],"teach":[{"h":"The idea","list":["F is the oral bioavailability factor: the proportion of a given dose that reaches the systemic circulation, between 0 and 1.","It appears only as a multiplier of the dose in Cp = {{frac:F ka D0|VD(ka - k)}} (e^(-kt) - e^(-ka t)), so its effect is the same as giving a smaller dose completely.","The peak and the area under the curve scale with F; the timing of the peak does not.","A capital F in an equation is itself the signal that the route is oral.","Her slide \"Concentration of Drug in Plasma Following a Single Oral Dose\" prints the equation with every symbol labelled."]}],"cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Concentration of Drug in Plasma Following a Single Oral Dose\"; 09.21 lecture","quote":"what fraction of this oral dose do we expect to be absorbed by the body and available for the body to use, right? When we give a drug IV, then that F is assumed to be one."},{"id":"m5-c20","tier":"new","exam":2,"module":5,"lecture":"L06","topic":"oral","sub":"peak","concept":"significance-of-params","skill":"recall","source":"slide","stem":"Which of the following is a use of the absorption rate constant, the time to peak and the maximum concentration?","options":[{"t":"assessing the onset of action","correct":true,"why":"Onset is the time at which the concentration first reaches a therapeutic level, so it is governed by how quickly the rising limb climbs. A product with a larger absorption rate constant reaches that level sooner. This is a direct clinical consequence of the input kinetics."},{"t":"estimating the glomerular filtration rate","why":"Filtration is a renal elimination process and is estimated from creatinine clearance, which has nothing to do with how fast an oral dose is absorbed. None of these three parameters carries information about the kidney. Selecting it imports a quantity from the elimination and clearance material into a list about input."},{"t":"deciding whether elimination is zero order or first order","why":"Picking this treats the absorption parameters as reporting on the output side. The order of elimination is judged from the shape of the terminal decline, which is governed by k, not by ka, the time to peak or the peak."},{"t":"calculating the total body clearance","why":"Picking this takes the input parameters for the output side. Clearance (Cl) is found from the dose and the area under the curve, or as k × VD, the elimination rate constant times the volume of distribution. ka, tmax and Cmax describe how fast the drug arrives, not how fast the body removes it."}],"teach":[{"h":"What they are used for","t":"Her slide \"Significance of Absorption Rate Constants, tmax, and Cmax\" lists five uses of ka (the absorption rate constant), tmax (the time to peak) and Cmax (the peak concentration):","list":["predicting peaks and troughs in repeated dosing;","comparing products for bioequivalence;","choosing a route and a dosage form;","assessing onset of action, the time at which the concentration first reaches an effective level;","relating the concentration to the pharmacological effect."],"after":"Every use is about input and its consequences, not about elimination."}],"cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Significance of Absorption Rate Constants, tmax, and Cmax\"","quote":"Bioequivalence studies – comparing rates of absorption from chemically equivalent products"},{"id":"m6b-c03","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"add","concept":"after-infusion-stops","skill":"apply","source":"both","stem":"The first of a series of intravenous (IV) infusions ends. What governs the plasma concentration from that moment until the next infusion begins?","options":[{"t":"First-order decline from the end level","correct":true,"why":"With the input stopped, only elimination is left, and it is first order. The concentration falls as C = C0e^(-kt) with the end-of-infusion value as C0, which is why that value has to be found first."},{"t":"Zero-order decline at the infusion rate","why":"This reverses input and output. Once the infusion stops the input plays no further part, and the body removes a constant fraction per hour, not a constant amount."},{"t":"A continued rise towards R/Cl","why":"This treats the input as still running. The rise towards {{frac:R|Cl}} happens only while drug is going in; when the pump stops, the concentration is at its highest for that infusion and can only fall."},{"t":"A steady level until the next infusion","why":"This confuses the plateau of a continuous infusion with the gap between two short ones. A level holds steady only while rate in equals rate out, and between infusions the rate in is zero."}],"teach":[{"h":"The idea","list":["Every intermittent-infusion problem is two Module 3 pieces in turn: first the rise during the infusion, then the decline after it stops."]},{"h":"After the infusion stops","list":["Only first-order elimination is left: C = Cpeak e^(-kt), where Cpeak is the concentration when the infusion ended and t is the time since it ended, not since it started."]},{"h":"Her Example 4 drawn out","fig":"two_infusions","list":["300 mg is infused over 2 hours, so R = 150 mg/hr; k is 0.15 hr⁻¹ and VD is 15 L. Each infusion rises to 17.28 mg/L; the second runs from 6 to 8 hours.","At 12 hours the first infusion, declining for 10 hours, contributes 3.86 mg/L and the second, declining for 4 hours, 9.48 mg/L: 13.34 mg/L in all."]}],"cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"What is the plasma drug concentration at the end of the first infusion?\"; 09.28 lecture","quote":"What happens when we stop the infusion? It's only elimination. ... So that C0 is gonna be the concentration at the end of the infusion, right?"},{"id":"m6b-c04","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"add","concept":"time-since-that-infusion","skill":"apply","source":"both","stem":"A 2-hour infusion runs from 0 to 2 hours; a second identical infusion runs from 6 to 8 hours. To find the first infusion's contribution at 12 hours, what value of t goes into e^(−kt)?","options":[{"t":"10 hours","correct":true,"why":"The first infusion stopped at 2 hours and has been declining since, so at 12 hours it has declined for 12 − 2 = 10 hours. Its contribution is its end-of-infusion concentration multiplied by e^(-10k)."},{"t":"4 hours","why":"Choosing this measures the first infusion from the end of the second. Four hours is the decline time of the second infusion (12 − 8); the first stopped 6 hours earlier and has fallen further."},{"t":"12 hours","why":"Choosing this measures from the start of the first infusion, not its end. For the 2 hours it ran, the concentration was rising; the decline begins when it stops."},{"t":"6 hours","why":"This reads the gap between the two starts as the decline time. Six hours is when the second infusion began, which says nothing about how long the first has been declining at 12 hours."}],"teach":[{"h":"The idea","list":["Draw her number line: mark each start, each end, and the time asked for.","The t of each infusion is measured from its own end.","So the two infusions get different values of t at the same clock time."]},{"h":"Her Example 4 drawn out","fig":"two_infusions","list":["300 mg is infused over 2 hours, so R = 150 mg/hr; k is 0.15 hr⁻¹ and VD is 15 L. Each infusion rises to 17.28 mg/L; the second runs from 6 to 8 hours.","At 12 hours the first infusion, declining for 10 hours, contributes 3.86 mg/L and the second, declining for 4 hours, 9.48 mg/L: 13.34 mg/L in all."]}],"cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"What is the plasma drug concentration 4 hours after the cessation of the second infusion?\"; 09.28 lecture","quote":"here is the part that you need to pay attention to. We are interested in the concentration from this red infusion where we stop at time 2. All the way out here on our number line at 12 hours later. So, the time that we're interested in is going to be the time that we're interested 12 minus 2, OK? So, 10 hours."},{"id":"m6b-c05","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"add","concept":"infusions-add","skill":"tell","source":"both","stem":"Two identical intravenous (IV) infusions of the same drug are given 6 hours apart. Why can the plasma concentration at a later time be found by adding what is left of each?","options":[{"t":"Elimination is first order","correct":true,"why":"With first-order, linear kinetics a constant fraction is removed per hour whatever else is present, so the first infusion declines the same way whether or not a second is given. Each infusion is its own curve, and the curves add: superposition."},{"t":"Both infusions are zero-order inputs","why":"Choosing this attaches the additivity to the input. A zero-order input sets how drug goes in; the curves can be added because the output is first order and unchanged by the amount present."},{"t":"The second infusion restarts the clock for both","why":"Choosing this collapses two declines into one. The second infusion does not change what the first left behind; the first keeps declining on its own timetable, so its t is measured from its own end."},{"t":"The concentrations are the same at every time","why":"This reads \"identical infusions\" as identical curves at the same clock time. Each reaches the same end-of-infusion concentration, 17.3 mg/L in her example, but at different times, so at any one moment they have declined by different amounts."}],"teach":[{"h":"The idea","list":["This is superposition, from repeated IV (intravenous) bolus dosing, applied to infusions.","It rests on the same assumptions as for repeated bolus doses: first-order elimination, and a half-life and clearance that do not change with more doses.","So the same drug at the same rate for the same duration reaches the same Cpeak (end-of-infusion concentration) every time."]}],"cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Administering One or More Doses by IV Infusion\"; 09.28 lecture","quote":"the concentrations from each administration of the dose will be additive over time"},{"id":"m6b-c06","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"why","concept":"intermittent-vs-bolus","skill":"tell","source":"both","stem":"A drug is given either as repeated intravenous (IV) bolus injections or as repeated 2-hour IV infusions, same dose and same interval. Where does each interval's peak occur?","options":[{"t":"Bolus: when the dose is given; infusion: when the infusion ends","correct":true,"why":"A bolus goes in all at once, so its peak is the instant it is given. An infusion keeps adding drug until the pump stops, so its highest point is the end of the infusion, where the decline starts."},{"t":"Both when the dose starts","why":"This treats the infusion as a bolus. When an infusion starts nothing has gone in yet; the concentration rises during the infusion and peaks only at its end."},{"t":"Both at the end of the dosing interval","why":"This reverses peak and trough. The end of the interval, just before the next dose, is where the concentration is lowest for either route."},{"t":"Bolus: when the infusion ends; infusion: when the dose is given","why":"This swaps the two routes. A bolus has no infusion time, and an infusion has no single moment at which the dose is in."}],"teach":[{"h":"The idea","list":["Repeated IV (intravenous) bolus and intermittent infusion share the equations for what happens between doses.","They differ in where the peak sits and in how it is found.","Bolus: C0 = {{frac:D0|VD}}, the dose over the apparent volume of distribution.","Infusion: the infusion equation with t equal to the infusion time."]},{"h":"Repeated bolus against intermittent infusion","table":{"head":["","Repeated IV bolus","Intermittent IV infusion"],"rows":[["Input","Instantaneous","Zero order, for the infusion time"],["Peak","At the dose, C0 = {{frac:D0|VD}}","At the end of the infusion, {{frac:R|VD k}}(1 - e^(-kt))"],["Between doses","First-order decline","First-order decline"],["Why chosen","Simple","A lower peak, better tolerated"]]}}],"cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Rationale\" and \"Administering One or More Doses by IV Infusion\"; 09.28 lecture","quote":"instead of putting all the drug into the body all at once, we are going to put the drug into the body via a zero order, like we just first, just talked about a zero-order constant process"},{"id":"m6b-c20","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"why","concept":"infusion-time-in-rise","skill":"apply","source":"both","stem":"A second 2-hour intravenous (IV) infusion of the same dose starts 6 hours after the first began. What value of t goes into (1 − e^(−kt)) to find the concentration at the end of the second infusion?","options":[{"t":"2 hours","correct":true,"why":"The (1 − e^(−kt)) term describes the rise while drug is going in, so its t is how long the pump ran. Every infusion in the series runs 2 hours, so each reaches the same end-of-infusion concentration, 17.28 mg/L in her Example 4."},{"t":"6 hours","why":"Choosing this puts the clock time into an equation that only uses how long drug has been going in. The 6 hours places the second infusion on the time line; its rise depends only on its own 2-hour duration."},{"t":"8 hours","why":"This confuses when the infusion ends with how long it ran. Eight hours is where the second peak sits on the number line; the rise to that peak took 2 hours."},{"t":"4 hours","why":"Choosing this attaches the gap between the infusions to the rise. During the gap the first dose declines; the second dose rises over the same 2-hour climb from zero as the first."}],"teach":[{"h":"The idea","list":["Two different times are used in these problems.","The rise of each infusion uses its own duration.","The decline of each infusion uses the time since its own end.","The clock time serves only to work out those two."]},{"h":"The common error","list":["Using 6 hours in the infusion equation. The (1 - e^(-kt)) term applies only while drug is going in, so its t is the infusion time, 2 hours, for every infusion in the series."]}],"cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Administering One or More Doses by IV Infusion\"; 09.28 lecture","quote":"1 minus E to the minus KT where this T. Is the infusion time."},{"id":"m6b-c07","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oeq","concept":"oral-vs-bolus-ss-equation","skill":"tell","source":"both","stem":"Cmax∞ = {{frac:FD0|VD}} × {{frac:1|1 − e^(−kτ)}} × e^(−k·tmax∞). What marks this as the steady-state peak for an oral dose rather than for a repeated intravenous (IV) bolus?","options":[{"t":"The F and the tmax","correct":true,"why":"F is bioavailability, which an IV dose does not need, and tmax is the time to peak, which a bolus lacks because it peaks at the moment of the dose. Remove those two and what is left, {{frac:D0|VD}} × {{frac:1|1 − e^(−kτ)}}, is the bolus Cmax∞."},{"t":"The τ","why":"This reads the dosing interval as an oral feature. Every multiple-dose regimen has a τ, bolus or oral, so τ cannot tell the two apart."},{"t":"The accumulation factor {{frac:1|1 − e^(−kτ)}}","why":"Choosing this attaches accumulation to the oral route. The same factor appears in the repeated-bolus equations, because accumulation depends on k and τ, not on how the dose enters."},{"t":"The VD","why":"The volume of distribution turns an amount into a concentration for every route, so VD is in the bolus equation too."}],"teach":[{"h":"The idea","list":["On the equation sheet the oral and bolus steady-state peaks sit near each other and look alike.","Her test: an oral equation carries F (bioavailability), and an oral peak needs tmax (the time to peak) found first."]},{"h":"The symbols","list":["Symbols: ka is the absorption rate constant, k the elimination rate constant, τ the dosing interval, F the bioavailability, D0 the dose and VD the apparent volume of distribution. ∞ marks steady state."]}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Peak, Trough and Average Plasma Concentrations at Steady State\"; 09.28 lecture","quote":"what tells you that this is for an oral dose? F is one thing. ... What else tells us? Team Max, right? Because when we're giving a bolus dose, when does the max occur? Initially"},{"id":"m6b-c08","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"ossc","concept":"tmax-ss-depends","skill":"tell","source":"both","stem":"The time to peak after a single oral dose depends on k and ka. What does the time to peak at steady state, tmax∞, depend on?","options":[{"t":"k, ka and τ","correct":true,"why":"The steady-state expression has τ inside the logarithm, because drug left from earlier doses changes when the rising and falling rates balance. Change how often the drug is given, and tmax∞ must be recalculated."},{"t":"k and ka only","why":"Choosing this carries the single-dose result over unchanged. The τ terms in tmax∞ are the whole difference between the two equations."},{"t":"The dose and VD","why":"Choosing this brings in the quantities that set the height of the peak. Neither appears in tmax∞; a larger dose raises Cmax∞ and leaves the timing where it was."},{"t":"F and the dose","why":"This confuses when the peak occurs with how high it is. F and the dose scale the concentration; the time to peak is set by the two rate constants and, at steady state, the interval."}],"teach":[{"h":"The idea","list":["The single-dose tmax and the steady-state tmax∞ share k (the elimination rate constant) and ka (the absorption rate constant).","tmax∞ adds τ, the dosing interval.","A regimen does not change k or ka, so the interval is the only thing a regimen can change that moves tmax∞."]},{"h":"The steady-state time to peak","list":["Time to peak: tmax∞ = {{frac:1|ka - k}} ln[{{frac:ka(1 - e^(-kτ))|k(1 - e^(-ka τ))}}]."]}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Time to Peak at Steady State\"; 09.28 lecture","quote":"for at steady state following multiple oral dosing. Depends on K, KA and tau. OK. Single oral dose, K and KA."},{"id":"m6b-c09","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"ossc","concept":"interval-changes-tmax-cmax","skill":"apply","source":"both","stem":"A drug given orally every 6 hours is changed to every 12 hours, same dose. Which of the following must be recalculated?","options":[{"t":"tmax∞ and Cmax∞","correct":true,"why":"Both carry τ (the dosing interval): tmax∞ (the time to peak at steady state) inside its logarithm, and Cmax∞ (the steady-state peak) through the accumulation factor and through tmax∞ itself. A new interval means a new time to peak and a new peak."},{"t":"k and ka","why":"This treats the rate constants as adjustable. They belong to the drug and the formulation; a regimen changes only the dose and the interval."},{"t":"ClT and VD","why":"Picking this treats total clearance (ClT) and the volume of distribution (VD) as things a regimen sets. Both belong to the patient and the drug and do not move when the interval changes; they are inputs to every steady-state equation, not results of the regimen."},{"t":"Nothing at steady state","why":"This reads steady state as a fixed property of the drug. Steady state is a balance between what is given and what is cleared, and giving the same dose half as often halves the input."}],"teach":[{"h":"The idea","list":["Dose and interval are the two things a regimen can change.","The interval reaches into tmax∞, Cmax∞, Cmin∞ and Cavg∞: the time to peak, peak, trough and average at steady state.","The dose scales the concentrations without moving tmax∞."]},{"h":"Where τ sits in the oral equations","list":["Time to peak: tmax∞ = {{frac:1|ka - k}} ln[{{frac:ka(1 - e^(-kτ))|k(1 - e^(-ka τ))}}].","Peak: Cmax∞ = {{frac:FD0|VD}} ({{frac:1|1 - e^(-kτ)}}) e^(-k tmax∞)."]},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Time to Peak at Steady State\"; 09.28 lecture","quote":"So if we change the dosing interval, we need to recalculate TMax. Right? And it will also change our CMax."},{"id":"m6b-c10","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"ossc","concept":"tmax-ss-shorter","skill":"apply","source":"both","stem":"A drug is given orally at a fixed dose and interval. How does the time to peak at steady state compare with the time to peak after the first dose?","options":[{"t":"It is generally shorter","correct":true,"why":"At steady state drug from earlier doses is already in the body, so elimination runs at a higher rate from the moment the new dose is taken, and the rising and falling rates balance sooner. In her tetracycline example tmax falls from 3.1 hours to 2.06 hours."},{"t":"It is generally longer","why":"This runs the wrong way. Accumulated drug does not delay the peak; it brings it forward, because the elimination rate is already high when absorption begins."},{"t":"It is the same","why":"Choosing this uses single-dose reasoning, where only k and ka matter. The steady-state tmax has τ in it as well, and her worked values differ: 3.1 against 2.06 hours."},{"t":"It is twice as long","why":"This attaches a fixed multiple to a relation that has none. The direction is shorter, and the size of the change depends on k, ka and τ together."}],"teach":[{"h":"The idea","list":["From the first dose to steady state, the peak comes earlier and higher.","Earlier because of tmax∞, the time to peak at steady state; higher because of the accumulation factor."]},{"h":"First dose against steady state: her tetracycline example","list":["250 mg every 8 hours, F 0.75, VD 112.5 L; t½ (half-life) 10 hr, so k is 0.0693 hr⁻¹; ka is 0.9 hr⁻¹."],"table":{"head":["","First dose","At steady state"],"rows":[["tmax","{{frac:ln(ka/k)|ka - k}} = 3.1 hr","tmax∞, with τ in it: 2.06 hr"],["Cmax","The single-dose equation at tmax: 1.35 mg/L","Cmax∞, with the accumulation factor: 3.4 mg/L computed (she says 3.3)"]]},"after":"From the first dose to steady state, tmax falls and Cmax rises by the accumulation factor {{frac:1|1 - e^(-kτ)}}, 2.35 here."}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Example 1\"; 09.28 lecture","quote":"That steady state TMAX is going to be lower than the T-Max of the first dose, OK?"},{"id":"m6b-c13","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"regimen-parameters","skill":"recall","source":"both","stem":"Which two parameters can be adjusted in developing a dosage regimen?","options":[{"t":"Dose size and dosing interval","correct":true,"why":"How much drug is given and how often are the two things a prescriber decides. Everything else in the equations, such as k, the half-life, clearance and VD, belongs to the drug and the patient."},{"t":"Clearance and volume of distribution","why":"Choosing this treats patient parameters as adjustable. Clearance and VD are what the patient brings; the regimen is designed around them, not by changing them."},{"t":"Half-life and dose","why":"The dose is right and the half-life is not. The half-life follows from k, which the drug and the patient set, so a regimen cannot lengthen or shorten it."},{"t":"Bioavailability and dosing interval","why":"The interval is right and F (bioavailability) is not. F is a property of the drug and its formulation; changing the product might change it, but the regimen does not set it."}],"teach":[{"h":"The idea","list":["A regimen sets two things: the dose and the interval.","The rest of the equation is fixed by the drug and the patient.","Her slides \"Altering Dose\" and \"Altering Dosing Interval\" list the effects of each change."]},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Multiple-Dosage Regimens\"; 09.28 lecture","quote":"So the only things that we can change. Are the dose, so the, the size of the dose, how much drug we give, and the dosing intervals. OK. We don't change clearance, we don't change half-life, we don't change volume and distribution."},{"id":"m6b-c14","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"increase-dose-effects","skill":"apply","source":"both","stem":"Which of the following would be expected at steady state if the oral dose of a drug is doubled with no change to the dosing interval?","options":[{"t":"Higher concentrations and a larger swing between peak and trough","correct":true,"why":"A larger dose raises every concentration in proportion, so the peak, trough and average all rise, and the peak-to-trough gap, a fixed fraction of the peak, grows with them. Compliance usually does not change, because the patient takes the same number of doses."},{"t":"Higher concentrations and a smaller swing between peak and trough","why":"This pairs the right direction for the level with the wrong one for the swing. Doubling the dose doubles the peak and the trough, so the difference between them doubles too."},{"t":"The same average concentration, reached sooner","why":"This confuses the dose with the half-life. The dose sets how high the plateau is, not how fast it is reached; steady state still takes 3 to 5 half-lives."},{"t":"A longer time to peak","why":"Choosing this attaches the dose to tmax. Neither the single-dose tmax nor tmax∞ contains the dose, so doubling it leaves the timing alone."}],"teach":[{"h":"The idea","list":["Method 1 for altering steady state: change the dose, keep the interval.","Fluctuation, or swing, is how far the level falls from the peak to the trough within one dosing interval.","The whole curve scales up: peak, trough and average all double when the dose doubles, and so does the gap; in her Example 1 it doubles from 40 to 80 mg/L.","The trough stays the same fraction of the peak, because that fraction, e^(−kτ), depends on the interval and k, not on the dose.","Her slide \"Altering Dose\" calls this \"increased fluctuation\"."]},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slides \"Altering Dose\" and \"Altering Dose, second slide\"; 09.28 lecture","quote":"if we increase the dose, we expect increased concentration and increased fluctuation between peaks and troughs"},{"id":"m6b-c15","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"increase-interval-effects","skill":"apply","source":"both","stem":"A 500-mg oral dose given every 4 hours is changed to 500 mg every 8 hours. What is expected at steady state?","options":[{"t":"Lower concentrations, a larger swing, and better compliance","correct":true,"why":"The same dose half as often halves the input, so the average falls. Each dose also has longer to be eliminated before the next, so the level drops further between doses and the swing grows. Fewer doses a day are easier to keep to."},{"t":"Lower concentrations, a smaller swing, and better compliance","why":"Picking this reads a longer interval as a steadier level. The same 500 mg every 8 hours instead of every 4 gives each dose twice the time to be eliminated before the next, so the trough falls further and the swing grows."},{"t":"Higher concentrations, a smaller swing, and better compliance","why":"Picking this reads a longer interval as more drug. The dose is unchanged at 500 mg and is given half as often, so the input per day halves and Cavg∞ (the average steady-state concentration), {{frac:F D0|Cl τ}}, falls as τ (the dosing interval) doubles."},{"t":"The same concentrations, the same swing, and better compliance","why":"Picking this leaves τ (the dosing interval) out of the average. Cavg∞ is {{frac:F D0|Cl τ}}: with the same 500 mg dose and τ doubled from 4 to 8 hours, the average halves, and the swing grows."}],"steps":[{"k":"algebra","t":"Doses per day: {{frac:24 hr|4 hr}} = 6, so 6 × 500 mg = 3000 mg a day; {{frac:24 hr|8 hr}} = 3, so 3 × 500 mg = 1500 mg a day","why":"Half as many doses a day halves the daily input, from 3000 to 1500 mg; the drug and the patient are unchanged, so clearance is unchanged and the level has to fall."},{"k":"algebra","t":"Cavg∞ = {{frac:F D0|Cl τ}}: τ doubles from 4 to 8 hr, so Cavg∞ falls to {{frac:4|8}} = 0.5 of its value; the steady-state concentrations are lower","why":"The average steady-state concentration carries the interval in its denominator, with the dose, F and clearance unchanged, so doubling τ halves the average."},{"k":"setup","t":"Swing: Cmin∞ = Cmax∞ e^(−kτ); with τ = 8 hr the fraction left at the trough is e^(−8k) = (e^(−4k))², smaller than with τ = 4 hr, so the trough falls further below the peak","why":"Each dose now has 8 hours rather than 4 to be eliminated before the next arrives. The fraction of the peak left at the trough is squared, so the trough is a smaller fraction of the peak: a larger swing."},{"k":"setup","t":"Compare: lower average (half), larger swing (trough fraction squared), 3 doses a day instead of 6: lower concentrations, a larger swing, better compliance","why":"Each part follows from the longer interval: half the daily input gives a lower level, a longer decline gives a larger swing, and three doses a day are easier to keep to than six."}],"givens":[["D0","500-mg","unchanged: the same dose at both intervals"],["τ","every 4 hours","the old interval: 6 doses a day"],["τ new","every 8 hours","the new interval: 3 doses a day; Cavg∞ falls to {{frac:4|8}} = 0.5"]],"check":{"t":"The dose is unchanged, so the level cannot rise: the same 500 mg given half as often, 3 times a day instead of 6, halves the input, and each dose has twice as long to fall before the next. Average and trough both move down, the trough further."},"teach":[{"h":"The idea","list":["Method 2 for altering steady state: change the interval, keep the dose."]},{"h":"What each change does at steady state","table":{"head":["Change","Steady-state concentration","Fluctuation, peak to trough","Patient compliance"],"rows":[["Increase the dose, same τ","Higher","Larger","Usually no change"],["Decrease the dose, same τ","Lower","Smaller","Usually no change"],["Increase τ, same dose (less often)","Lower","Larger","Better"],["Decrease τ, same dose (more often)","Higher","Smaller","Worse"]]}},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slides \"Altering Dosing Interval\" and \"Altering Dosing Interval, second slide\"; 09.28 lecture","quote":"increasing the dosing interval. Right? Increasing the dosing interval means that we're giving more time in between doses, decreased steady-state concentration, increased fluctuation between peak to trough. Increase patient compliance, generally."},{"id":"m6b-c16","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"oparam","concept":"decrease-interval-fluctuation","skill":"apply","source":"both","stem":"The dosing interval of an oral regimen is shortened from 8 hours to 4 hours, same dose. Why does the fluctuation between peak and trough decrease?","options":[{"t":"Less time passes for the level to fall","correct":true,"why":"The trough is where the next dose interrupts the decline. With 4 hours instead of 8, the decline stops earlier, so the trough sits closer to the peak, a larger fraction of it, even though both peak and trough are higher."},{"t":"Less drug accumulates, so the peaks are lower","why":"This has accumulation backwards. A shorter interval leaves more of each dose behind when the next arrives, so more accumulates and the peaks are higher; the swing shrinks because the troughs rise by a larger fraction than the peaks."},{"t":"The elimination rate constant falls","why":"Choosing this changes k. The regimen changes only how often the drug is given; k, the half-life and clearance are unchanged."},{"t":"Absorption becomes slower","why":"Choosing this changes ka. Each dose is absorbed with the same ka whatever the interval; the smaller swing comes from the shorter decline between doses."}],"teach":[{"h":"The idea","list":["Her reasoning: 3 to 5 half-lives clear most of a dose.","A shorter interval cuts into that time, so the level does not get near the bottom of the curve before the next dose arrives.","So Cmax∞ and Cmin∞ both go up; what decreases is how far the level falls between them.","In her Example 1 the trough is a quarter of the peak every 8 hours and half of it every 4 hours."]},{"h":"Her Example 1 three ways","fig":"dose_interval","after":"Her Example 1 (each dose adds 40 mg/L, t½ 4 hours) every 8 hours, every 4 hours, and at double the dose."}],"cite":"6a---Multiple-Oral-Doses.pdf, slide \"Altering Dosing Interval, second slide\"; 09.28 lecture","quote":"if we decrease that, um, dosing interval, then maybe we're cutting into that 3 to 5 half-lives a little bit more, so we're not going all the way to the bottom of that curve"},{"id":"cq1-1","multi":true,"tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"first","concept":"first-order-rate-depends","skill":"tell","dupOf":"m1-ord-c04","source":"both","stem":"Which of the following is true about a process in which the rate depends on the concentration? Select all that apply.","options":[{"t":"The half-life depends on the concentration of the drug present.","correct":false,"why":"A half-life that changes with concentration belongs to zero order, where t½ = {{frac:C0|2k}}. A rate that depends on concentration is first order, and its half-life is 0.693 over k, the same at every level. She said: \"if the rate depends on concentration, remember our half-life is independent\"."},{"t":"The half-life is independent of concentration.","correct":true,"why":"A rate that depends on concentration is first order, and the first-order half-life is t½ = {{frac:0.693|k}}: neither term contains a concentration, so the time to halve is the same from any starting level. In her words, \"our half-life is 0.693 over K, doesn't change\"."},{"t":"The rate equation is dC/dt = −kC.","correct":true,"why":"dC/dt is the rate, and here it equals k times C, so the rate changes whenever the concentration changes: the definition of first order. As she put it, \"DCDT is our rate, and this one says that the rate is equal to our K times concentration\"."},{"t":"The rate equation is dC/dt = −k.","correct":false,"why":"No C appears on the right, so the rate stays the same whatever the concentration: that is the zero-order rate law, the answer to the flipped version of this item (\"rate is independent of the concentration\": A and D)."}],"teach":[{"h":"The idea","list":["\"Depends on the concentration\" describes the rate, the amount removed per unit of time. It changes with the level in first order: {{frac:dC|dt}} = −kC.","In the same first-order process the half-life and the fraction removed per unit of time do not change: t½ = {{frac:0.693|k}}.","Zero order is the mirror image: the rate is constant ({{frac:dC|dt}} = −k) and the half-life changes with the starting concentration (t½ = {{frac:C0|2k}}).","Options a and b contradict each other, so a select-all can never key both."]}],"cite":"Quiz 1 (26 Aug), question 1; her spoken review, transcript 08-26; Introduction.pdf, slides on first- and zero-order processes","quote":"if the rate depends on concentration, remember our half-life is independent, our half-life is 0.693 over K, doesn't change"},{"id":"cq1-2","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"zero","concept":"zero-order-defn","skill":"recall","dupOf":"m1-ord-c01","source":"both","stem":"Which of the following is true about a zero-order process?","options":[{"t":"The elimination rate is at its highest when the amount of drug in the body is at its highest.","correct":false,"why":"This describes first order, where the rate is k times the amount, so the most drug gives the fastest loss. It is her key for the flipped version, which asked about a first-order process: \"The rate is highest at the top of the curve when the concentration is highest\"."},{"t":"The elimination rate is at its highest when the amount of drug in the body is at its lowest.","correct":false,"why":"Neither order behaves this way. In first order the rate falls as the amount falls; in zero order the rate does not change at all."},{"t":"The elimination rate is independent of the amount of drug in the body.","correct":true,"why":"Zero order means {{frac:dC|dt}} = −k with no amount or concentration term, so the same quantity leaves in each unit of time however much drug is present. This is the flipped form of her first-order item, whose key was the rate being highest when the amount is highest."},{"t":"The elimination rate increases as a function of time.","correct":false,"why":"In zero order the rate is constant over time, and in first order it falls over time as the amount falls. No elimination process in this course speeds up as time passes."}],"teach":[{"h":"The idea","list":["Zero order: {{frac:dC|dt}} = −k. The same amount or concentration leaves per unit of time, independent of how much is present.","First order: {{frac:dC|dt}} = −kC. The rate is highest at the start, when the concentration is highest, and falls with it.","In zero order the fraction lost per hour grows as the amount shrinks; in first order the fraction stays fixed."]}],"cite":"Quiz 1 (26 Aug), question 2; her spoken review of the flipped version, transcript 08-26; Introduction.pdf slide 17","quote":"The rate is highest at the top of the curve when the concentration is highest"},{"id":"cq2-4","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"load","concept":"loading-purpose","skill":"recall","dupOf":"inf-c11","stem":"Why is a loading dose used?","options":[{"t":"To immediately obtain a therapeutic plasma concentration","correct":true,"why":"An infusion alone takes three to five half-lives to reach steady state. A loading dose puts the steady-state amount, Css × VD (the steady-state concentration times the apparent volume of distribution), into the body at once, so the therapeutic level is there from the start and the infusion then holds it."},{"t":"To reduce the adverse effects associated with the drug","correct":false,"why":"Picking this reads a dosing device as a safety device. A loading dose raises the concentration faster, which brings any concentration-related adverse effect forward rather than reducing it. The plateau Css = {{frac:R|Cl}} depends on the infusion rate R and clearance Cl, not on the loading dose."},{"t":"To improve patient adherence","correct":false,"why":"This answer confuses a kinetic quantity with a behavioural one. Adherence concerns how reliably a patient takes a regimen over days or weeks. A loading dose is a one-time amount, Css × VD, chosen so the target level exists from the first minute; it says nothing about how reliably later doses are taken."},{"t":"To reduce the elimination half-life","correct":false,"why":"Picking this reads the half-life as something a dose can shorten. The half-life is a property of the drug and the patient, set by k = {{frac:Cl|VD}}, where k is the elimination rate constant. No dose changes k, Cl or VD; a loading dose only changes how soon the target concentration is reached."}],"teach":[{"h":"The idea","list":["The time to steady state is set by the half-life alone: three to five half-lives, whatever the rate.","When that wait is too long, a loading dose DL = Css × VD supplies the steady-state amount at once.","DL = Css × VD because Cp = {{frac:DB|VD}}: the amount in the body at the plateau is the target concentration times the volume it spreads through.","With the right loading dose the level stays flat at Css: the bolus part falls as C0e^(−kt) while the infusion part rises as Css(1 − e^(−kt)), and the two add to Css at every time."]}],"cite":"Canvas Quiz 2 (Modules 2–3), question 4; 3IntravenousInfusions.pdf, slide \"IV Bolus Loading Dose and Continuous IV Infusion\""},{"id":"cq4-2","type":"numeric","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"multi","sub":"ssbolus","concept":"cmax-ss","skill":"multidose","stem":"What is the expected maximum steady-state concentration following IV bolus injections of 17 mg/kg to a 75 kg male every 8 hours? The drug has an elimination half-life of 4 hours, and the apparent volume of distribution is 15% of body weight. Give your answer in (mg/L), rounded to the nearest tenth (one decimal place) with no units.","units":"mg/L","answer":151.1,"tol":7.6,"steps":[{"k":"setup","t":"Cmax∞ = {{frac:C0|1 − e^(−kτ)}}, with C0 = {{frac:D0|VD}}","why":"\"IV bolus injections … every 8 hours\" and \"maximum steady-state concentration\" name the repeated IV bolus block at steady state. The peak at the plateau is the single-dose peak divided by the fraction not yet eliminated at each dose."},{"k":"unit","t":"D0 = 17 mg/kg × 75 kg = 1275 mg; VD = 0.15 × 75 kg = 11.25 L; C0 = {{frac:1275 mg|11.25 L}} = 113.3 mg/L","why":"Both the dose and the volume are given per kilogram of body weight, so both are scaled to the 75 kg patient before anything else. mg over L is mg/L."},{"k":"algebra","t":"k = {{frac:0.693|4 hr}} = 0.1733 hr⁻¹; e^(−kτ) = e^(−0.1733 × 8) = e^(−1.386) = 0.250","why":"Eight hours is two half-lives, so one quarter of a dose remains when the next arrives. The exponent is dimensionless: reciprocal hours times hours."},{"k":"algebra","t":"Cmax∞ = {{frac:113.3 mg/L|1 − 0.250}} = {{frac:113.3|0.750}} = 151.1 mg/L","why":"Dividing by 0.75 is the accumulation factor 1.33: the steady-state peak is one third higher than the first-dose peak."},{"k":"round","t":"151.1","why":"Her key is 151.1 with a margin of 5%, so 143.5 to 158.7 scores. One decimal place was asked for, and Canvas took the number with no unit."}],"setup":{"eq":"cmax-ss","pre":["thalf-first","cp-db-vd"],"why":"\"IV bolus injections\" \"every 8 hours\" and \"maximum steady-state concentration\", so the repeated IV bolus block at steady state. Dose per kg, VD per kg, t½ and τ are given and Cmax∞ is asked, so Cmax∞ = {{frac:C0|1 − e^(−kτ)}}. k first from the half-life, and C0 from the scaled dose over the scaled volume."},"asks":"Cmaxss","givens":[["D0","17 mg/kg","scaled to 75 kg: 1275 mg, the numerator of C0"],["weight","75 kg","scales both the dose and the volume"],["τ","every 8 hours","the exponent kτ = 0.1733 × 8 = 1.386"],["t½","4 hours","gives k = {{frac:0.693|4}} = 0.1733 hr⁻¹"],["VD","15% of body weight","scaled to 75 kg: 11.25 L, the denominator of C0"]],"check":{"t":"C0 is {{frac:17|0.15}} = 113.3 mg/L per dose and 8 hours is two half-lives, so a quarter is left at each new dose; the peak is C0 over 0.750, a third more than 113.3: 151.1, between 113.3 and 2 × 113.3.","lo":113.3,"hi":226.6},"teach":[{"h":"The idea","list":["Scale per-kilogram values to the patient first; the mg/kg and L/kg cancel against the same body weight.","τ equal to two half-lives leaves 25% at each dose, so the factor is 1 ÷ 0.75.","The same line, with e^(−kτ) multiplied in on top, gives the trough."]}],"cite":"Canvas Quiz 4 (Modules 6–7a), question 2; 6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Concentration of Drug in the Body at Steady-State Following Repeated IV Bolus Injections\""},{"id":"cq4-4","type":"numeric","tier":"new","exam":2,"module":6,"lecture":"L08","topic":"intermit","sub":"add","concept":"sum-two-infusions","skill":"multidose","stem":"Four hundred milligrams of an antibiotic was infused intravenously over a period of 2 hours. Eight hours after the start of the first infusion, a second 400-mg dose was infused again over a period of 2 hours. The half-life of the antibiotic is approximately 4 hours and the apparent volume of distribution is approximately 20 L. What is the plasma drug concentration 4 hours after the cessation of the second infusion? Give your answer in mg/L rounded to the nearest tenth (one decimal place) with no units.","units":"mg/L","answer":10.6,"tol":0.53,"steps":[{"k":"setup","t":"Each infusion ends at Cend = {{frac:R|k × VD}}(1 − e^(−k × 2 hr)); then Cp = Cend e^(−k t₁) + Cend e^(−k t₂), one term per infusion","why":"The two infusions are added (superposition). Each is a 2-hour infusion that ends at the same concentration because the dose, the time and the patient are the same; after it stops, each decays by first-order elimination from its own end time."},{"k":"unit","t":"R = {{frac:400 mg|2 hr}} = 200 mg/hr; k = {{frac:0.693|4 hr}} = 0.1733 hr⁻¹; Cl = k × VD = 0.1733 × 20 L = 3.465 L/hr","why":"The rate is the dose over the infusion time, in mg/hr. Clearance comes from k and VD because the infusion line wants Cl."},{"k":"algebra","t":"Cend = {{frac:200 mg/hr|3.465 L/hr}}(1 − e^(−0.1733 × 2)) = 57.72 × (1 − 0.7071) = 16.90 mg/L","why":"57.72 mg/L would be the plateau if the drip ran on; after two hours, half a half-life, it has reached 29.3% of that."},{"k":"algebra","t":"Times since each infusion ended: first ended at 2 hr, so 12 hr have passed at t = 14 hr; second ended at 10 hr, so 4 hr. Cp = 16.90 e^(−0.1733 × 12) + 16.90 e^(−0.1733 × 4) = 16.90 × 0.125 + 16.90 × 0.500 = 2.11 + 8.45 = 10.56 mg/L","why":"The second infusion started 8 hours after the first began, so it ran from 8 to 10 hours; 4 hours after its end is 14 hours. Twelve hours is three half-lives (one eighth left), four hours is one half-life (one half left)."},{"k":"round","t":"10.6","why":"Her key is 10.6 with a margin of 5%, so 10.1 to 11.1 scores. Leaving out the first infusion gives 8.45, too low; treating each infusion as a 400 mg bolus into 20 L gives 20 × 0.125 + 20 × 0.500 = 12.5, too high, because each 2-hour infusion ends at 16.90 mg/L."}],"setup":{"eq":"cp-after-stop","pre":["thalf-first","cl-k-vd","cp-infusing"],"why":"Two 2-hour infusions and a level \"4 hours after the cessation of the second infusion\": intermittent infusions, added. Dose, infusion time, t½ and VD are given and Cp is asked, so each end level decays from its own end time and the two are summed. k first, then Cl = k × VD, then the infusion line."},"asks":"Cp","givens":[["D0","Four hundred milligrams","with the infusion time gives R = {{frac:400|2}} = 200 mg/hr"],["infusion time","over a period of 2 hours","R = 200 mg/hr; t = 2 hr in 1 − e^(−kt)"],["second start","Eight hours after the start of the first infusion","the second infusion runs 8 to 10 hr"],["t½","approximately 4 hours","gives k = {{frac:0.693|4}} = 0.1733 hr⁻¹"],["VD","approximately 20 L","in Cl = kVD = 3.465 L/hr"],["t","4 hours after the cessation of the second infusion","the second term decays 4 hr, the first 12 hr"]],"check":{"t":"Each infusion ends at 16.90 mg/L. Four hours is one half-life, so the second leaves 8.45; the first, 12 hours or three half-lives on, leaves an eighth, 2.11. The sum is between 8.45 and 2 × 16.90.","lo":8.45,"hi":33.8},"teach":[{"h":"The idea","list":["Work one infusion to its end level with the infusion line, then let each copy decay from its own stopping time, then add.","Count the clock from the start of the first infusion: starts at 0 and 8 hours, ends at 2 and 10 hours, the question asks about 14 hours.","Half-life arithmetic checks the exponentials: 12 hours is three half-lives (0.125), 4 hours is one (0.5)."]}],"cite":"Canvas Quiz 4 (Modules 6–7a), question 4; 6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Administering One or More Doses by IV Infusion\" and \"Example 4\""},{"id":"cq4-6","type":"numeric","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"ossc","concept":"tmax-ss","skill":"multidose","stem":"A 74-kg patient was administered a 750 mg oral dose of a new drug every 8 hours. The drug has an oral bioavailability of 92%, apparent volume of distribution of 0.29 L/kg, elimination half-life of 5 hours, and the absorption half-life of 1.5 hour. When does the expected maximum concentration of drug in the plasma at steady-state occur? Give your answer in hours rounded to the nearest tenth (one decimal place) with no units.","units":"hr","answer":2.6,"tol":0.13,"steps":[{"k":"setup","t":"tmax∞ = {{frac:1|ka − k}} ln[{{frac:ka(1 − e^(−kτ))|k(1 − e^(−kaτ))}}]","why":"\"Oral dose … every 8 hours\" and \"when does the … maximum concentration … at steady-state occur\" ask for the time of the peak within an interval at the plateau. Only the two rate constants and τ enter; the dose, F, VD and the weight are not needed."},{"k":"algebra","t":"k = {{frac:0.693|5 hr}} = 0.1386 hr⁻¹; ka = {{frac:0.693|1.5 hr}} = 0.462 hr⁻¹","why":"Each half-life gives its own rate constant. The absorption half-life is the shorter one, so ka is the larger constant, as it must be for an immediate-release product."},{"k":"algebra","t":"e^(−kτ) = e^(−0.1386 × 8) = 0.330, so 1 − 0.330 = 0.670; e^(−kaτ) = e^(−0.462 × 8) = 0.0248, so 1 − 0.0248 = 0.975","why":"Both accumulation terms are evaluated at τ = 8 hours. Absorption is nearly complete within an interval (0.975), elimination is not (0.670)."},{"k":"algebra","t":"tmax∞ = {{frac:1|0.462 − 0.1386}} ln[{{frac:0.462 × 0.670|0.1386 × 0.975}}] = {{frac:1|0.3234}} ln(2.291) = 3.092 × 0.829 = 2.56 hr","why":"The ratio inside the log is 2.291 and its natural log is 0.829; dividing by the difference of the constants gives hours. The single-dose tmax for the same constants would be 3.72 hr, so the steady-state peak comes earlier."},{"k":"round","t":"2.6","why":"Her key is 2.6 with a margin of 5%, so 2.5 to 2.7 scores. The single-dose line, {{frac:ln(ka ÷ k)|ka − k}}, gives 3.72 hr with the same constants; at steady state the peak comes earlier, so the τ terms are needed."}],"setup":{"eq":"tmax-ss","pre":["thalf-first","thalf-abs"],"why":"\"oral dose … every 8 hours\" and \"when does the expected maximum concentration … at steady-state occur\", so the multiple oral block, the time-of-peak line. Two half-lives and τ are given and tmax∞ is asked; F, VD, the dose and the weight are not in the line. k and ka first, each from its half-life."},"asks":"tmaxss","givens":[["weight","74-kg","not needed: tmax∞ has no volume in it"],["D0","750 mg","not needed: tmax∞ does not depend on the dose"],["τ","every 8 hours","in 1 − e^(−kτ) and 1 − e^(−kaτ)"],["F","92%","not needed: F scales the height of the curve, not its timing"],["VD","0.29 L/kg","not needed"],["t½","5 hours","gives k = {{frac:0.693|5}} = 0.1386 hr⁻¹"],["absorption t½","1.5 hour","gives ka = {{frac:0.693|1.5}} = 0.462 hr⁻¹"]],"check":{"t":"The steady-state peak must fall inside the 8-hour interval and comes earlier than a first-dose peak, since drug from earlier doses is being eliminated while the new dose absorbs: 2.6 hours, between 0 and 8.","lo":0,"hi":8},"teach":[{"h":"The idea","list":["The steady-state peak time needs ka, k and τ only; extra data in the stem (F, VD, weight, dose) is for other parts of the same problem.","At steady state the peak arrives earlier than after a single dose, because drug left from earlier doses is already being eliminated while the new dose is absorbed.","Each half-life in the stem is converted to its own rate constant with 0.693."]}],"cite":"Canvas Quiz 4 (Modules 6–7a), question 6; 6a---Multiple-Oral-Doses.pdf, slide \"Example 1\" (tmax at steady state)"},{"id":"cq4-8","type":"numeric","tier":"new","exam":2,"module":6,"lecture":"L09","topic":"multoral","sub":"ossc","concept":"dose-for-cavg","skill":"multidose","stem":"A patient is to take a medication by mouth every 8 hours. The medication has an oral bioavailability of 83%, an absorption half-life of 90 minutes, total body clearance of 3.0 L/hr, and apparent volume of distribution of approximately 25 L. What is an appropriate dose to achieve an average plasma drug concentration of 25 mg/L in this patient? Give your answer in mg rounded to the nearest whole number with no units.","units":"mg","answer":723,"tol":36,"steps":[{"k":"setup","t":"Cavg∞ = {{frac:F × D0|Cl × τ}}, so D0 = {{frac:Cavg∞ × Cl × τ|F}}","why":"\"By mouth every 8 hours\" and \"average plasma drug concentration\" name the average steady-state line of the multiple oral block, rearranged for the dose. Clearance is given directly, so k and VD are not needed; the absorption half-life and VD are extra data for this part."},{"k":"algebra","t":"D0 = {{frac:25 mg/L × 3.0 L/hr × 8 hr|0.83}} = {{frac:600 mg|0.83}} = 722.9 mg","why":"mg/L × L/hr × hr leaves mg: the amount cleared in one interval at the target average. Dividing by F scales it up to the dose that has to be swallowed for 83% of it to reach the blood."},{"k":"round","t":"723","why":"Her key is 723 with a margin of 5%, so 687 to 759 scores. Multiplying by F instead of dividing gives 600 × 0.83 = 498 mg, less than the 600 mg that has to be absorbed, which cannot be right. The whole number was asked for."}],"setup":{"eq":"cavg-ss","pre":[],"why":"\"by mouth every 8 hours\" and \"average plasma drug concentration\", so the multiple oral block, the average line. Cl, τ, F and the target Cavg∞ are given and the dose is asked, so Cavg∞ = {{frac:F × D0|Cl × τ}} is rearranged for D0. No hinge: clearance is given, so k and VD stay unused."},"asks":"D0","givens":[["τ","every 8 hours","multiplies clearance: Cl × τ = 3.0 × 8 = 24 L"],["F","83%","written 0.83, the denominator"],["absorption t½","90 minutes","not needed: the average concentration does not depend on ka"],["Cl","3.0 L/hr","in the numerator with τ"],["VD","approximately 25 L","not needed: clearance is given"],["Cavg∞","25 mg/L","the target, in the numerator"]],"check":{"t":"Holding 25 mg/L while 24 L is cleared per interval needs 600 mg absorbed; with only 0.83 of the dose absorbed, the dose must be larger than 600 mg: {{frac:600|0.83}} = 723 mg.","lo":600},"teach":[{"h":"The idea","list":["The average steady-state concentration depends on the dosing rate F × D0 ÷ τ and on clearance, and on nothing else: not on ka, not on VD.","Cl × τ × Cavg∞ is the amount of drug cleared per interval; the dose has to replace it, scaled up by F.","She rounds a dose to a usable strength on worksheets; here Canvas asked for the whole number."]}],"cite":"Canvas Quiz 4 (Modules 6–7a), question 8; 6a---Multiple-Oral-Doses.pdf, slide \"Peak, Trough and Average Plasma Concentrations at Steady State\""},{"id":"cq4-9","type":"numeric","tier":"new","exam":2,"module":7,"lecture":"L10","topic":"bioavail","sub":"fabs","concept":"fabs-from-clearance","skill":"bioavail","stem":"What is the absolute bioavailability of a drug for which a 500 mg dose resulted in an AUC of 139 (mg/L)hr? The elimination half-life of the drug is 4.5 hr and the apparent volume of distribution is 18 L. Give your answer as a decimal rounded to the nearest hundredth with no units.","units":"(as a decimal fraction)","answer":0.77,"tol":0.023,"steps":[{"k":"setup","t":"Fabs = {{frac:AUCpo|AUCIV}} with the same dose, and AUCIV = {{frac:DIV|Cl}}, Cl = k × VD","why":"\"Absolute bioavailability\" with one AUC given and no IV AUC: the IV area has to come from the dose and the clearance, which the half-life and the volume supply. With equal doses the dose ratio is 1."},{"k":"algebra","t":"k = {{frac:0.693|4.5 hr}} = 0.154 hr⁻¹; Cl = 0.154 hr⁻¹ × 18 L = 2.772 L/hr; AUCIV = {{frac:500 mg|2.772 L/hr}} = 180.4 (mg/L)hr","why":"hr⁻¹ × L is L/hr, and mg over L/hr is mg·hr/L, the unit of an AUC. This is the area the same 500 mg would give intravenously."},{"k":"algebra","t":"Fabs = {{frac:139|180.4}} = 0.771","why":"With equal doses the dose ratio is {{frac:500|500}} = 1 and drops out, leaving Fabs = {{frac:AUCpo|AUCIV}} = {{frac:139|180.4}} = 0.771, a dimensionless fraction. The oral area is 77 per cent of the IV area, so 77 per cent of the oral dose reached the circulation."},{"k":"round","t":"0.77","why":"Her key is 0.77 with a margin of 3%, so 0.75 to 0.79 scores. Two decimal places were asked for, as a decimal, not a percentage."}],"setup":{"eq":"f-abs","pre":["thalf-first","cl-k-vd","div-cl-auc"],"why":"\"absolute bioavailability\" with an oral AUC, t½ and VD and no IV AUC, so the bioavailability block. The IV AUC is not given, so it comes from DIV = Cl × AUCIV with Cl = k × VD; then Fabs is the ratio of the two areas, the doses being equal."},"asks":"F","givens":[["D0","500 mg","the numerator of AUCIV = {{frac:DIV|Cl}}; the dose ratio is 1"],["AUCpo","139 (mg/L)hr","the numerator of the area ratio"],["t½","4.5 hr","gives k = {{frac:0.693|4.5}} = 0.154 hr⁻¹"],["VD","18 L","in Cl = kVD = 0.154 × 18 = 2.772 L/hr"]],"check":{"t":"Clearance 2.772 L/hr means the 500 mg would give 180.4 (mg/L)hr if all of it reached the blood; the oral 139 is about three-quarters of that, so F is about 0.77, between 0 and 1.","lo":0,"hi":1},"teach":[{"h":"The idea","list":["When the IV curve is not given, dose over clearance is the IV AUC.","Equal oral and IV doses make the dose ratio 1, so F is the ratio of the areas.","Report F as a decimal with two places (0.77), or as 77%; never 0.771 when two places are asked."]}],"cite":"Canvas Quiz 4 (Modules 6–7a), question 9; 7a---Bioavailability-and-Bioequivalence.pdf, slide \"Absolute Bioavailability\" (equation) and the in-class activity of 09.30, question 3"},{"id":"cq5-1","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"thalf","concept":"thalf-double-teff","skill":"apply","dupOf":"pd-c20","source":"slide","stem":"For a drug that displays linear, first-order pharmacokinetics, what is the impact on duration of activity if there is an increase in elimination half-life?","options":[{"t":"There is a no change to the duration of activity.","correct":false,"why":"Picking this treats the duration as set by the dose alone. In teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}) the half-life multiplies the whole expression, so a longer t½ with the same dose and volume keeps the level above the minimum effective concentration (MEC) for longer."},{"t":"Duration of activity will increase.","correct":true,"why":"A longer half-life means slower elimination, so the level takes longer to fall from C0 to the MEC. teff is in direct proportion to t½: twice the half-life, twice the duration, as when decreased renal or hepatic function prolongs t½."},{"t":"Duration of activity will decrease.","correct":false,"why":"Picking this reverses the direction. A longer t½ means a smaller elimination rate constant k, so the level falls more slowly and stays at or above the MEC for longer, not shorter."}],"teach":[{"h":"The idea","list":["teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}): t½ multiplies everything, so teff changes in direct proportion to the half-life.","The dose sits inside the logarithm: doubling the dose adds one half-life to teff; it does not double it.","Decreased renal or hepatic elimination prolongs t½, prolongs the effect, and raises the possibility of toxicity."]}],"cite":"Canvas Quiz 5 (Modules 7b and 8), question 1; 7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\" and 10 \"Effect of Elimination Half-life on Duration of Activity\""},{"id":"cq5-6","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"linear","concept":"nl-saturation-features","skill":"recall","dupOf":"nl-c04","source":"slide","stem":"Which of the following is true regarding drugs that display nonlinear pharmacokinetics?","options":[{"t":"Parameters do not change when different or multiple doses of a drug are given","correct":false,"why":"Picking this takes the definition of linear pharmacokinetics for nonlinear. With a nonlinear drug an increased dose or chronic administration changes the parameters: clearance falls and the half-life lengthens as the concentration rises."},{"t":"Half-life changes as dose is increased","correct":true,"why":"With saturable elimination t½ = VD({{frac:0.693|Vmax}})(KM + Cp), so a larger dose, giving a higher Cp, gives a longer half-life. It is one of the characteristics of saturation kinetics."},{"t":"The principle of superposition applies at steady-state.","correct":false,"why":"Picking this carries a linear rule into saturation kinetics. Superposition adds the curves of separate doses, which needs each dose to lose the same fraction per hour; once elimination saturates, a later dose is cleared more slowly, so the curves do not simply add."},{"t":"The AUC is proportional to the amount of bioavailable drug.","correct":false,"why":"Picking this describes dose-independent kinetics. With saturable elimination the AUC (area under the curve) is disproportional to the amount of bioavailable drug: past a certain dose it rises more than in proportion."}],"teach":[{"h":"The idea","list":["Linear: parameters such as half-life and clearance do not change when different or multiple doses are given.","Saturation kinetics: half-life changes as dose is increased, and the AUC is disproportional to the amount of bioavailable drug.","t½ = VD({{frac:0.693|Vmax}})(KM + Cp) rises with Cp; Cl = {{frac:Vmax|KM + Cp}} falls with Cp."]}],"cite":"Canvas Quiz 5 (Modules 7b and 8), question 6; 8 - Nonlinear PK.pdf, slides 3 \"Linear vs. Nonlinear Pharmacokinetics\" and 6 \"Saturation Kinetics\""},{"id":"fig-ord-1","skill":"order","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"decide","concept":"order-from-linear-straight","source":"both","stem":"Plasma concentration is plotted against time on the axis shown, and the points fall on a straight line. What does this indicate about the process removing the drug?","img":"ord_linear_straight","options":[{"t":"It is zero order","correct":true,"why":"The concentration axis is marked 0, 25, 50, 75, 100, so equal distances up the axis are equal amounts of drug. A straight line on that axis therefore means the same amount is lost in every hour, which is zero order: a rate that does not depend on how much drug is present."},{"t":"It is first order","correct":false,"why":"First order removes a fixed fraction rather than a fixed amount, so on an evenly spaced axis it draws a curve that flattens as concentration falls. Choosing this reads the straightness without checking the axis; a straight line indicates first order only on an axis that steps by a factor of ten."},{"t":"The order cannot be decided without the half-life","correct":false,"why":"The half-life is a consequence of the order, not a precondition for finding it. Picking this reverses the order of work: the shape of the line on a known axis settles the order, and only then does the matching half-life relation apply, C0/2k0 for zero order or {{frac:0.693|k}} for first."},{"t":"The order cannot be decided without knowing the dose","correct":false,"why":"The dose sets where the curve starts, not how it falls. Reaching for this confuses the intercept with the slope: C0 moves the whole line up or down the axis, while the order is carried entirely by the shape between the points."}],"teach":[{"h":"The idea","list":["The concentration axis is evenly spaced: the gap from 25 to 50 is the same distance as the gap from 75 to 100.","On an evenly spaced axis, the steepness of the line is the amount of drug lost per hour; a straight line has one steepness, so the same amount leaves every hour.","Losing the same amount every hour is the definition of zero order, written {{frac:dC|dt}} = −k0, where k0 is the zero-order rate constant."]},{"h":"The relation","list":["Integrating {{frac:dC|dt}} = −k0 gives C = C0 − k0t: a straight line with intercept C0 (the concentration at time zero) and slope −k0.","A rate constant reported in mg/hr or mcg/mL/hr belongs to a zero-order process; one reported in hr⁻¹ belongs to a first-order process."]}],"quote":"if you look at that scale and you see that it is not changing by regular one infinite, or it’s increasing by a a function of 10, then that tells you that it is a logarithmic scale","audit":"Redrawn on the evenly spaced axis of the zero-order slide.","teachImg":"slide_Introduction_p20","cite":"Introduction.pdf slide 17"},{"id":"fig-ord-3","skill":"read","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"plots","concept":"order-from-semilog-straight","source":"both","stem":"Plasma concentration is plotted against time on the axis shown, and the points fall on a straight line. What does this indicate about the process removing the drug?","img":"ord_semilog_straight","options":[{"t":"It is first order","correct":true,"why":"The concentration axis runs 1, 10, 100, 1000, so each equal step up the axis multiplies the concentration by ten. A straight line on a multiplying axis means a constant fraction is lost per hour, which is first order."},{"t":"It is zero order","correct":false,"why":"This comes from reading the line as straight without reading the axis, and the axis is not evenly spaced: 1 to 10 covers the same distance as 100 to 1000. Her instruction is to look at the scale before judging the line."},{"t":"It is first order only if the axis is labelled as logarithmic","correct":false,"why":"The word is usually absent, which she flags directly, so this answer means waiting for a label that never arrives and classifying nothing. The tick values are the evidence: 1, 10, 100, 1000 is a decade scale whether or not anything on the figure says so."},{"t":"The order cannot be decided from a graph alone","correct":false,"why":"The shape on a stated axis is exactly what settles it, and she says a data set or a curve will be given for this purpose. Picking this treats the graph as decoration rather than as the evidence, when the axis and the line together carry the answer."}],"teach":[{"h":"The idea","list":["Read the tick values, not the line. The ticks are 1, 10, 100 and 1000, so each equal distance up the axis multiplies the concentration by ten.","First order gives ln C = ln C0 − kt, where C0 is the concentration at time zero and k the elimination rate constant.","So plotting the logarithm of concentration against time gives a straight line. An axis whose ticks step by tens plots that logarithm for you."]},{"h":"The relation","list":["On an axis of base-ten decades the relation is log C = log C0 − {{frac:kt|2.3}}, so the slope read off the figure is −{{frac:k|2.3}}, not −k.","Multiplying that slope by 2.3 recovers the elimination rate constant."]}],"quote":"I expect for you, because you will see graphs like this, and this word will not be over here most of the time. you’ve got to pay attention to the axis","audit":"Redrawn from the points on her semi-logarithmic slide: 200, 93, 44, 21, 10, 4.9 and 2.3 at hours 0 to 6.","teachImg":"slide_Introduction_p24","cite":"Introduction.pdf slide 21"},{"id":"fig-ord-4","skill":"order","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"plots","concept":"order-from-semilog-curve","source":"both","stem":"Plasma concentration is plotted against time on the axis shown. What does the shape of this line indicate about the process removing the drug?","img":"ord_semilog_curve","options":[{"t":"It is zero order","correct":true,"why":"The axis steps by factors of ten, which is the axis that straightens a first-order decline. This line bends away downward instead, so the process is not first order; a constant amount lost per hour drops through the lower decades faster and faster, giving exactly this plunge."},{"t":"It is first order","correct":false,"why":"First order is what this axis straightens, so a first-order decline would be a straight line here. Choosing this reads the axis correctly and then ignores what the line does on it, which reverses the test: on a decade axis, straight means first order and bent means it is not."},{"t":"The drug follows a two-compartment model","correct":false,"why":"A two-compartment decline bends the other way, steep first and then shallower, because the fast distribution phase finishes and the slower elimination phase takes over. This line does the opposite, starting shallow and steepening, so reading it as two compartments has the direction backwards."},{"t":"The concentrations were measured incorrectly","correct":false,"why":"A smooth, regular bend is a kinetic signal rather than noise; measurement error scatters points about a line instead of curving them consistently in one direction. Reaching for this dismisses the shape of the curve, which is the evidence."}],"teach":[{"h":"The idea","list":["A decade axis, with ticks that step by tens, plots the logarithm of concentration.","First order becomes a straight line on it, because ln C falls by a constant amount each hour. Zero order does not, because C itself falls by a constant amount each hour."]},{"h":"Why zero order plunges at the end","list":["Under C = C0 − k0t the same amount leaves every hour, so the last of the drug disappears over the same time as the first of it.","Near the bottom of the axis, that fixed amount is a huge fraction of what is left. On a multiplying axis, a huge fraction lost is a long way down, so the line steepens."]},{"h":"The two-step test","list":["Read the axis, then read the line. Evenly spaced axis plus straight line: zero order. Decade axis plus straight line: first order. Either axis with a bend: the other order."]}],"audit":"A constant-rate decline on the same decade axis as the straight-line figure.","teachImg":"slide_Introduction_p20","cite":"Introduction.pdf slides 17–21"},{"id":"fig-ord-5","skill":"read","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"plots","concept":"semilog-axis-recognition","source":"transcript","stem":"A concentration axis is marked 1, 10, 100, 1000 at equal spacing, with no other label. Which statement about that axis is correct?","img":"ord_semilog_straight","options":[{"t":"a straight line on this axis indicates a first-order process","correct":true,"why":"Moving one tick multiplies the value by ten every time, from 1 to 10 and again from 100 to 1000. That is what a logarithmic axis does: it turns multiplication into equal distance, which is why a fixed-fraction process draws a straight line on it."},{"t":"the axis is evenly spaced in concentration","why":"Selecting this reads the evenly spaced tick marks as evenly spaced values. The marks are equally far apart, but the values at them multiply by ten at each step: 1 to 10 adds nine units and 100 to 1000 adds nine hundred, so equal distances are equal multiples, not equal amounts."},{"t":"the axis cannot be treated as logarithmic unless it is labelled as such","why":"Picking this waits for a label that is usually missing. The tick values are the evidence: 1, 10, 100, 1000 step by a factor of ten, which only a logarithmic axis does, so the axis is treated as logarithmic whether or not the word log is printed beside it."},{"t":"a straight line on this axis indicates a zero-order process","why":"This answer reads the straightness without reading the axis. Zero order loses the same amount per hour and is straight only where equal distances are equal amounts; on this axis equal distances are equal multiples, so a straight line means a fixed fraction lost per hour, which is first order."}],"teach":[{"h":"The idea","list":["Read two neighbouring tick values and divide. If the answer is the same multiple each time, such as ten, the axis is logarithmic.","If the difference is the same each time, such as twenty-five, the axis is evenly spaced.","The word will not be printed on most figures; the tick values are always there, so they are the reliable evidence."]},{"h":"What follows once it is recognised","list":["On a decade axis, a straight line means first order. The slope is −{{frac:k|2.3}} for base-ten decades, where k is the elimination rate constant.","On an evenly spaced axis, a straight line means zero order. The slope is −k0 directly, where k0 is the zero-order rate constant."]}],"quote":"Notice that it doesn’t say. Log","audit":"Drawn with no axis label, the case she describes.","teachImg":"slide_Introduction_p23","cite":"Introduction.pdf slides 20–21"},{"id":"e2r-6","tier":"new","exam":2,"module":5,"lecture":"L06","multi":true,"topic":"oral","sub":"peak","concept":"oral-dose-doubling","skill":"apply","source":"slide","stem":"Which of the following would you expect with a 2-fold increase in oral dose? (Select all that apply)","options":[{"t":"Decreased AUC","why":"Picking this reverses the direction. With first-order kinetics AUC = {{frac:F D0|Cl}}, so doubling D0 doubles the area."},{"t":"Increased AUC","correct":true,"why":"AUC = {{frac:F D0|Cl}}: the dose is in the numerator and nothing else changes, so the area doubles. Her slide \"Changing Dose\" shows AUC rising in proportion to the dose."},{"t":"Decreased Cmax","why":"Picking this reverses the direction. The dose multiplies the whole oral curve, Cp = {{frac:F ka D0|VD(ka − k)}}(e^(−kt) − e^(−ka t)), so the peak rises."},{"t":"Increased Cmax","correct":true,"why":"D0 multiplies the whole curve, Cp = {{frac:F ka D0|VD(ka − k)}}(e^(−kt) − e^(−ka t)), so the peak doubles along with every other point while its time stays the same."},{"t":"Decreased tmax","why":"Picking this lets the dose move the time of the peak. tmax = {{frac:ln(ka ÷ k)|ka − k}} holds only the two rate constants, so a larger dose leaves it where it was."},{"t":"Increased tmax","why":"Picking this reads a bigger dose as taking longer to reach its peak. tmax holds only ka and k; the dose scales the curve up without shifting it in time."}],"teach":[{"h":"Changing the oral dose","list":["Cmax and AUC rise in proportion to the dose; tmax does not change, because tmax = {{frac:ln(ka ÷ k)|ka − k}} has no dose in it (her slide \"Changing Dose\").","Her Quiz 3, question 3, asked the same point as \"the time needed to reach the maximum concentration depends on the rate constants for absorption and elimination\"."]}],"cite":"Exam 2 In-Class Review (handed out 7 Oct 2026), question 6; 5---Pharmacokinetics-of-Oral-Absorption.pdf, slide \"Changing Dose\""},{"id":"pd-c01","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"pd","concept":"pd-definition","skill":"recall","source":"slide","stem":"Which term describes the relationship between drug concentration at the site of action (receptor) and the observed pharmacologic response?","options":[{"t":"Pharmacodynamics","correct":true,"why":"Pharmacodynamics starts where pharmacokinetics stops: it takes the concentration at the receptor and links it to the response that concentration produces, which is what the drug does to the body once it arrives."},{"t":"Pharmacokinetics","why":"Choosing this takes the half of the relationship that comes first. Pharmacokinetics describes how the dose becomes a concentration over time; the response that concentration produces at the receptor is pharmacodynamics."},{"t":"Bioavailability","why":"Choosing this takes the arrival of the drug for its effect. Bioavailability is the rate and extent to which the active ingredient is absorbed and becomes available at the site of action; it ends where the receptor response begins."},{"t":"Duration of activity","why":"Choosing this takes one measure of the response for the whole relationship. Duration of activity, teff, is the time the plasma level stays at or above the minimum effective concentration; pharmacodynamics is the concentration–response link itself."}],"teach":[{"h":"Pharmacodynamics and exposure–response","list":["Pharmacodynamics (PD): the relationship between drug concentration at the site of action, the receptor, and the observed pharmacologic response.","Pharmacokinetics (PK) turns the dose into a concentration over time; PD turns that concentration into a response.","The PK–PD relationship is also called the exposure–response, concentration–response or concentration–effect relationship.","Exposure–response information is used to determine safety and efficacy in drug approval, to understand benefit–risk, and to derive dosing information."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 3 \"Pharmacodynamics\""},{"id":"pd-c02","tier":"new","exam":3,"module":9,"lecture":"L11","multi":true,"topic":"pkpd","sub":"pd","concept":"exposure-response-names","skill":"recall","source":"slide","stem":"The relationship between pharmacokinetics (PK) and pharmacodynamics (PD) is also referred to as which of the following? (Select all that apply)","options":[{"t":"exposure–response relationship","correct":true,"why":"Exposure is the pharmacokinetic side and response the pharmacologic observation. Joining them is the PK–PD relationship under its most common name."},{"t":"concentration–response relationship","correct":true,"why":"This names the same link with the plasma concentration as the measure of exposure: as the concentration at the receptor rises, the response rises toward its maximum."},{"t":"concentration–effect relationship","correct":true,"why":"Effect is the change in response that the concentration produces, so this third name again joins a PK quantity, the concentration, to a PD one, the effect."},{"t":"concentration–time relationship","why":"Choosing this takes the pharmacokinetic curve alone for the PK–PD link. Concentration against time, C = C0e^(−kt) after an IV bolus, has no response in it; PK–PD joins that concentration to an effect."},{"t":"rate–extent relationship","why":"Choosing this carries over the two parts of bioavailability, rate (read from tmax) and extent (read from AUC). Both describe how drug reaches the circulation, not the response it then produces."}],"teach":[{"h":"Pharmacodynamics and exposure–response","list":["Pharmacodynamics (PD): the relationship between drug concentration at the site of action, the receptor, and the observed pharmacologic response.","Pharmacokinetics (PK) turns the dose into a concentration over time; PD turns that concentration into a response.","The PK–PD relationship is also called the exposure–response, concentration–response or concentration–effect relationship.","Exposure–response information is used to determine safety and efficacy in drug approval, to understand benefit–risk, and to derive dosing information."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 3 \"Pharmacodynamics\""},{"id":"pd-c03","tier":"new","exam":3,"module":9,"lecture":"L11","multi":true,"topic":"pkpd","sub":"pd","concept":"exposure-response-uses","skill":"recall","source":"slide","stem":"Exposure–response information is used for which of the following? (Select all that apply)","options":[{"t":"to determine the safety and efficacy of drugs in the process of drug approval","correct":true,"why":"Exposure–response data show which exposures give the wanted effect and which give toxicity, which is the safety and efficacy evidence a drug needs for approval."},{"t":"to understand the benefit–risk of drugs during the drug approval process","correct":true,"why":"Benefit–risk weighs the effect gained at an exposure against the toxicity risked at it; both sides come from relating exposure to response, so the same data serve it."},{"t":"to derive dosing information","correct":true,"why":"A dose gives an exposure through the pharmacokinetics, and the exposure gives a response, so the dose for a target response can be worked back from the exposure–response relationship."},{"t":"to measure the absolute bioavailability of a tablet","why":"Choosing this takes a pharmacokinetic comparison for an exposure–response use. Absolute bioavailability, F = ({{frac:AUCpo|AUCIV}})({{frac:DIV|Dpo}}), compares two exposures with each other and never involves a response."},{"t":"to determine the elimination half-life of a drug","why":"Choosing this takes a pharmacokinetic parameter for a PD use. The half-life, t½ = {{frac:0.693|k}}, comes from concentrations over time alone; exposure–response information adds the response to those concentrations."}],"teach":[{"h":"Pharmacodynamics and exposure–response","list":["Pharmacodynamics (PD): the relationship between drug concentration at the site of action, the receptor, and the observed pharmacologic response.","Pharmacokinetics (PK) turns the dose into a concentration over time; PD turns that concentration into a response.","The PK–PD relationship is also called the exposure–response, concentration–response or concentration–effect relationship.","Exposure–response information is used to determine safety and efficacy in drug approval, to understand benefit–risk, and to derive dosing information."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 3 \"Pharmacodynamics\""},{"id":"pd-c04","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"doseresp","concept":"response-up-to-max","skill":"recall","source":"slide","stem":"Which of the following is true regarding the relationship of dose to pharmacologic effect?","options":[{"t":"Response rises with dose up to a maximum effect","correct":true,"why":"More dose puts more drug at the receptor, so more receptors are occupied and the response grows; once all are occupied the response cannot rise further, which sets the maximum effect."},{"t":"The response increases in direct proportion to the dose at every dose.","why":"Choosing this extends the steep low-dose part of the curve to every dose. Near the top a further dose change gives only a small increase, and the response levels off at its maximum."},{"t":"The onset, intensity, and duration of the effect depend on the dose alone, not on the pharmacokinetics.","why":"Choosing this drops half of the statement: onset, intensity and duration depend on the dose and the pharmacokinetics. The same dose acts longer when elimination is slower, because the level stays above the MEC longer."},{"t":"The response falls once the dose passes the dose that gives the maximum response.","why":"Choosing this reads the plateau as a peak. The curve rises to the maximum response and stays there; added dose finds no free receptors, so it adds no response, but it does not take response away."}],"teach":[{"h":"Dose, concentration and response","list":["As the dose increases, the concentration at the receptor site increases, and the response increases up to a maximum effect.","Response against dose on a linear scale rises steeply, then flattens: the same dose change gives a large increase at low doses and a small one near the maximum.","Response against log dose is a sigmoid (S-shaped) curve; the maximum is reached when all receptors become saturated.","Its middle portion is close to a straight line: effect against log concentration, with slope m.","Onset, intensity and duration of the effect depend on the dose and on the pharmacokinetics of the drug."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 4 \"Relationship of Dose to Pharmacologic Effect\""},{"id":"pd-c05","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"doseresp","concept":"dose-response-linear-plot","skill":"read","source":"slide","stem":"On a plot of pharmacologic response against drug dose on a linear scale, where does a given change in dose produce the smallest increase in response?","options":[{"t":"Near the maximum response","correct":true,"why":"Near the top most receptors are already saturated, so extra drug finds few receptors left to act on and the curve flattens; the dose change that gave a large rise early gives a small one here."},{"t":"At the lowest doses","why":"Choosing this reverses the two regions of the curve. At low doses the curve is steep, so a given dose change gives a large increase in response; the small increase comes near the top, where the curve flattens."},{"t":"Equally at every dose","why":"Choosing this treats the curve as a straight line. A straight line gives the same rise for the same dose step everywhere; this curve is steep early and then plateaus, so the same step does less and less."},{"t":"At the dose giving half of the maximum response","why":"Choosing this picks the middle of the curve, where it is still rising. The smallest gain per dose step is where the curve is flattest, at the top near the maximum response."}],"teach":[{"h":"Dose, concentration and response","list":["As the dose increases, the concentration at the receptor site increases, and the response increases up to a maximum effect.","Response against dose on a linear scale rises steeply, then flattens: the same dose change gives a large increase at low doses and a small one near the maximum.","Response against log dose is a sigmoid (S-shaped) curve; the maximum is reached when all receptors become saturated.","Its middle portion is close to a straight line: effect against log concentration, with slope m.","Onset, intensity and duration of the effect depend on the dose and on the pharmacokinetics of the drug."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 4 \"Relationship of Dose to Pharmacologic Effect\" (left figure)"},{"id":"pd-c20","tier":"new","exam":3,"module":9,"lecture":"L11","topic":"pkpd","sub":"thalf","concept":"thalf-double-teff","skill":"apply","source":"slide","stem":"What is the expected change in the duration of activity of a single IV bolus dose if decreased elimination doubles the elimination half-life, with the dose and the volume of distribution unchanged?","options":[{"t":"teff doubles","correct":true,"why":"In teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}), t½ multiplies the whole expression and nothing else changes, so teff is directly proportional to t½: twice the half-life, twice the duration."},{"t":"teff increases by one half-life","why":"Choosing this carries the dose rule over to the half-life. Doubling the dose adds one t½ because the dose is inside the logarithm; t½ multiplies the whole expression, so doubling it doubles teff."},{"t":"teff is halved","why":"Choosing this reverses the direction. A longer half-life means slower elimination, so the level takes longer to fall to Ceff and the drug acts longer, not shorter."},{"t":"teff does not change, because the dose is the same","why":"Choosing this ties duration to the dose alone. Onset, intensity and duration depend on the dose and on the pharmacokinetics; from the same C0, a slower decline keeps the level above Ceff longer."}],"teach":[{"h":"Elimination half-life and duration","list":["Alteration of the elimination processes, excretion and metabolism, changes the t½ of the drug.","In certain disease states, pathophysiologic changes in hepatic or renal function decrease elimination, seen as a prolonged t½.","The prolonged t½ retains drug in the body, increasing the duration of activity and the possibility of toxicity.","teff = 1.44 t½ ln({{frac:D0|VD × Ceff}}): teff is directly proportional to t½, but not to the dose."]}],"cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\""},{"id":"nl-c02","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"linear","concept":"nl-linear-vs-nonlinear","skill":"tell","source":"both","stem":"2. What is the difference between linear and non-linear pharmacokinetics?","options":[{"t":"Linear parameters stay fixed with dose; nonlinear ones change with dose","correct":true,"why":"In linear pharmacokinetics the parameters do not change when different or multiple doses are given, so half-life and clearance stay fixed. In nonlinear pharmacokinetics a larger dose or chronic administration changes them, and a small dose change can give a large concentration change."},{"t":"Linear pharmacokinetics is zero order and nonlinear pharmacokinetics is first order","why":"Choosing this reverses the labels. Linear pharmacokinetics is the first-order elimination of most drugs; a saturable, nonlinear drug looks first order at low concentrations and zero order at high ones."},{"t":"In nonlinear pharmacokinetics the AUC rises in direct proportion to the dose","why":"Choosing this attaches the linear property to the wrong model. Proportional AUC (area under the curve) is curve C, dose-independent kinetics; with saturable elimination the AUC deviates from proportionality once the dose passes a certain point."},{"t":"Nonlinear processes affect absorption only, never elimination","why":"Choosing this narrows saturation to one step. A saturable process can occur anywhere in absorption, distribution, metabolism and excretion, and phenytoin, the usual example, shows saturable elimination."}],"teach":[{"h":"Linear and nonlinear","list":["Linear: parameters such as half-life and clearance do not change when different or multiple doses of a drug are given. Most drugs follow this.","Nonlinear (saturable, dose-dependent, capacity-limited): increased doses or chronic administration cause deviations from the single-dose profile. Example: phenytoin.","Clearance and half-life are usually not constant within nonlinear processes."]}],"cite":"Nonlinear-Solutions-2.pdf, question 2; 8 - Nonlinear PK.pdf, slides 3 \"Linear vs. Nonlinear Pharmacokinetics\" and 19 \"Summary\"; transcript 10-14"},{"id":"nl-c03","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmcp","concept":"nl-thalf-cl-trend","skill":"apply","source":"both","stem":"3. What changes in t½ and ClT are usually observed with increased concentrations of drugs that exhibit nonlinear pharmacokinetics?","options":[{"t":"t½ increases and ClT decreases","correct":true,"why":"t½ = VD(0.693/Vmax)(KM + Cp) grows as Cp grows, and ClT = Vmax/(KM + Cp) shrinks as Cp grows. In one phenytoin patient, going from 15 to 21 mg/L took the half-life from 1.87 to 2.34 days and clearance from 20.8 to 16.7 L/day."},{"t":"t½ decreases and ClT increases","why":"Choosing this runs both lines the opposite direction. Cp is added to KM in the numerator of the half-life line and in the denominator of the clearance line, so a higher concentration lengthens the half-life and lowers the clearance."},{"t":"Neither changes, because Vmax and KM are constants","why":"Choosing this treats the half-life and clearance as constants because Vmax and KM are. Both lines also contain Cp, which changes with dose, so neither stays fixed; that is what makes the drug nonlinear."},{"t":"t½ increases and ClT increases","why":"Choosing this gets the half-life right but moves clearance with it. Cp is in the denominator of ClT = Vmax/(KM + Cp), so clearance falls; a longer half-life with an unchanged volume also requires a lower clearance."}],"teach":[{"h":"Half-life and clearance depend on concentration","list":["t½ = VD({{frac:0.693|Vmax}})(KM + Cp): the half-life rises as Cp rises.","ClT = {{frac:Vmax|KM + Cp}}: clearance falls as Cp rises, because Cp is in the denominator.","VD in L/kg is multiplied by the weight first. With Vmax in mg/day, t½ comes out in days and ClT in L/day."]}],"cite":"Nonlinear-Solutions-2.pdf, question 3; 8 - Nonlinear PK.pdf, slides 17 and 18"},{"id":"nl-c04","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"linear","concept":"nl-saturation-features","skill":"recall","source":"slide","multi":true,"stem":"Which of the following are characteristics of saturation kinetics? (Select all that apply)","options":[{"t":"Elimination half-life changes as dose is increased","correct":true,"why":"With saturable elimination t½ = VD(0.693/Vmax)(KM + Cp), so a higher dose, giving a higher Cp, gives a longer half-life. In linear kinetics the half-life does not change with dose."},{"t":"AUC is disproportional to the amount of bioavailable drug","correct":true,"why":"Once elimination saturates, a larger dose is cleared more slowly, so the AUC (area under the curve) rises more than in proportion to the dose, curve A against the straight curve C."},{"t":"Other drugs using the same enzyme or carrier can affect saturation","correct":true,"why":"Two drugs that need the same enzyme or carrier compete for its limited capacity, so one can push the other toward saturation: a drug–drug interaction through a shared system."},{"t":"Metabolite ratios may change with dose","correct":true,"why":"If one metabolic route saturates at a higher dose while others do not, the share of drug going down each route changes, and so does the mix of metabolites."},{"t":"Clearance stays constant as the dose is increased, whatever the concentration","why":"Choosing this carries the linear rule into saturation kinetics. ClT = Vmax/(KM + Cp) falls as Cp rises, so clearance is usually not constant within nonlinear processes."},{"t":"AUC increases in direct proportion to the dose at every dose given","why":"Choosing this describes curve C, dose-independent kinetics, rather than saturable kinetics. With saturation the AUC versus dose line bends upward once the dose passes a certain point."}],"teach":[{"h":"Saturation kinetics","list":["Elimination kinetics is nonlinear, and the elimination half-life changes as dose is increased.","AUC is disproportional to the amount of bioavailable drug.","Saturation of capacity-limited processes may be affected by other drugs requiring the same enzyme or carrier-mediated system.","The composition or ratio of the metabolites may be affected by a change in the dose."]}],"cite":"8 - Nonlinear PK.pdf, slide 6 \"Saturation Kinetics\""},{"id":"nl-c05","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"linear","concept":"nl-phenytoin","skill":"recall","source":"both","stem":"Which of the following drugs is the prototypical example of nonlinear pharmacokinetics?","options":[{"t":"Phenytoin","correct":true,"why":"Phenytoin shows saturable elimination: once its level passes a certain point, small changes in dose lead to big changes in concentration. It also has a narrow therapeutic window, so its dose is set from the patient's own KM and Vmax."},{"t":"Procainamide","why":"Choosing this picks a drug worked with first-order lines. Procainamide is given a fixed half-life and volume of distribution, which is linear pharmacokinetics; phenytoin is the example of saturable elimination."},{"t":"Ciprofloxacin","why":"Choosing this picks a drug worked with linear lines. Ciprofloxacin is given an equivalent oral dose from F, the bioavailable fraction, a linear calculation; it is not the example of saturable elimination."},{"t":"Cefprozil","why":"Choosing this picks a drug dosed from creatinine clearance. Cefprozil is dosed with first-order lines, its renal elimination treated as linear, not saturable."}],"teach":[{"h":"Phenytoin","list":["The usual example of nonlinear pharmacokinetics: small changes in dose lead to big changes in concentration once a certain level is reached.","It has a narrow therapeutic window, so the dose rate is set from the patient's KM and Vmax, found from two dose rates and their steady-state levels."]}],"cite":"8 - Nonlinear PK.pdf, slide 3 \"Linear vs. Nonlinear Pharmacokinetics\" (\"Ex. phenytoin\"); transcript 10-14"},{"id":"nl-c06","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmcp","concept":"nl-vmax-def","skill":"recall","source":"slide","stem":"Which term describes the maximum elimination rate of a saturable elimination process?","options":[{"t":"Vmax","correct":true,"why":"Vmax is the maximum elimination rate: with nothing else going on, the fastest the enzyme system can remove the drug. It is a rate, an amount or concentration per unit time, such as mg/day."},{"t":"KM","why":"Choosing this swaps the two Michaelis-Menten parameters. KM, the Michaelis constant, reflects the capacity of the enzyme system and is a concentration, mg/L; it is not a rate."},{"t":"k′","why":"Choosing this takes the low-concentration constant for the maximum. k′ = {{frac:Vmax|KM}} is the first-order constant that applies only when Cp is much less than KM; it is not the top rate."},{"t":"R","why":"Choosing this mixes the dose rate with the elimination ceiling. R is the amount given per unit time; at steady state it equals the elimination rate at Css, which is always below Vmax."}],"teach":[{"h":"The two parameters","list":["Vmax: maximum elimination rate, units of concentration (or amount) per time.","KM: Michaelis constant, reflecting the capacity of the enzyme system, units of concentration.","For a given drug in a given patient both are constants; they differ from one patient to another."]}],"cite":"8 - Nonlinear PK.pdf, slides 7 \"Parameters\" and 8"},{"id":"nl-c07","tier":"new","exam":3,"module":8,"lecture":"L12","topic":"nonlin","sub":"kmcp","concept":"nl-km-def","skill":"recall","source":"both","stem":"Which term describes the constant, in units of concentration, that reflects the capacity of the enzyme system in Michaelis-Menten kinetics?","options":[{"t":"KM","correct":true,"why":"KM, the Michaelis constant, reflects the capacity of the enzyme system and carries units of concentration, such as mg/L. Because Cp is also a concentration, the two can be compared to tell first-order from zero-order behaviour."},{"t":"Vmax","why":"Choosing this swaps the two parameters. Vmax is the maximum elimination rate, in concentration or amount per time, such as mg/day; KM is the one in concentration units."},{"t":"Css","why":"Choosing this takes a patient's measured level for a property of the enzyme. Css is the steady-state concentration a dose rate produces and changes with the dose; KM stays the same for that drug and patient."},{"t":"VD","why":"Choosing this reaches for a familiar linear parameter. VD is the apparent volume of distribution, in litres; it appears in the nonlinear half-life line but says nothing about enzyme capacity."}],"teach":[{"h":"KM","list":["KM is the Michaelis constant: it reflects the capacity of the enzyme system and has units of concentration.","KM and Cp share units, so they can be compared: Cp far below KM gives first-order behaviour, Cp far above KM gives zero-order behaviour."]}],"audit":"Slide 8 prints KM = Michaelis constant (units of concentration), keyed here. The 10.14 lecture says of KM \"the units here ... are gonna be concentration per unit time\" and calls it \"not really a constant ... a hybrid constant\"; later in the same lecture she says KM is \"in concentration terms, so milligrams per liter\". Slide printed text keyed.","cite":"8 - Nonlinear PK.pdf, slides 7 \"Parameters\" and 8; transcript 10-14"},{"id":"fr-12a","tier":"new","exam":1,"module":3,"lecture":"L04","topic":"infusion","sub":"pre","concept":"cp-before-steady-state","skill":"infusion","source":"both","stem":"What is the plasma concentration at the end of a 2 hour infusion of a drug with a t½ of 3 hours and a VD of 18 L at a rate of 50 mg/hr?","options":[{"t":"3.03 mg/L","why":"Picking this undercounts how far the level has climbed. 3.03 mg/L is 25% of the 12.025 mg/L steady state; 2 hours at k = 0.231 hr⁻¹ reaches 37.0% of it, 4.45 mg/L."},{"t":"4.45 mg/L","correct":true,"why":"Css = {{frac:R|kVD}} = {{frac:50|0.231 × 18}} = 12.025 mg/L, and after 2 hours the level is 12.025 × (1 − e^(−0.462)) = 12.025 × 0.3700 = 4.449 mg/L."},{"t":"4.81 mg/L","why":"Picking this overcounts the climb. 4.81 mg/L is 40% of the steady state, more than the 37.0% that 1 − e^(−kt) gives for 2 hours with k = 0.231 hr⁻¹."},{"t":"31.5 mg/L","why":"Picking this puts the level above the steady state it climbs toward. An infusion approaches {{frac:R|Cl}} = 12.025 mg/L from below and never passes it."}],"steps":[{"k":"unit","t":"k = {{frac:0.693|3 hr}} = 0.231 hr⁻¹; Cl = kVD = 0.231 × 18 = 4.158 L/hr","why":"No clearance is given, so it is built from the half-life and the volume: k is 0.693 over t½ for a first-order process, and Cl = kVD. hr⁻¹ × L leaves L/hr."},{"k":"algebra","t":"{{frac:R|Cl}} = {{frac:50 mg/hr|4.158 L/hr}} = 12.025 mg/L","why":"At steady state the rate in, R, equals the rate out, Cl × Css, so Css is R over Cl, the level the infusion climbs toward. mg/hr over L/hr leaves mg/L; the hours cancel."},{"k":"algebra","t":"1 − e^(−0.231 × 2) = 1 − e^(−0.462) = 1 − 0.6300 = 0.3700","why":"During an infusion Cp = Css(1 − e^(−kt)), so 1 − e^(−kt) is the fraction of steady state reached after 2 hours. hr⁻¹ × hr cancels, so kt and the fraction have no units."},{"k":"algebra","t":"Cp = 12.025 × 0.3700 = 4.449 mg/L","why":"Cp = Css(1 − e^(−kt)): the steady-state level times the fraction reached. mg/L times a pure number stays mg/L. The answer must lie below 12.025 mg/L, and it does."},{"k":"round","t":"Cp = 4.45 mg/L","why":"4.449 mg/L to two decimal places, her value. Two hours is less than one half-life of 3 hours, so the level is still below half of the 12.025 mg/L steady state."}],"teach":[{"h":"An infusion, start to finish","list":["During the infusion: Cp = {{frac:R|Cl}}(1 − e^(−kt)), where {{frac:R|Cl}} is the steady-state concentration it climbs toward.","After it stops there is only first-order elimination: Cp = Cend e^(−kt), with t counted from the end of the infusion.","Two infusions add: the level at any time is the sum of what is left of each.","Changing the rate changes the steady-state concentration in proportion; the time to reach it stays 3 to 5 half-lives."]}],"quote":"OK, still going? All right, still working, are we done? OK. 4.45 mg per liter.","audit":"PollEv on page 25, 1 response on the capture. Keyed 4.45 mg/L (transcript 10-19). Recompute 12.025 × 0.36998 = 4.4490.","cite":"Final-Exam-Review-10.19.pdf slide 25 (PollEv); 3IntravenousInfusions.pdf, slide \"Drug Concentration at Steady-State\""},{"id":"x3-a-q1-zero","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"zero","concept":"zero-order-defn","skill":"tell","source":"both","multi":true,"dupOf":"cq1-1","stem":"Which of the following is true about a process in which the rate is independent of the concentration? Select all that apply.","options":[{"t":"The half-life depends on the concentration of the drug present.","correct":true,"why":"A rate independent of concentration is zero order, and the zero-order half-life is t½ = {{frac:C0|2k}}: the starting concentration sits in it, so a higher starting level takes longer to halve."},{"t":"The half-life is independent of concentration.","why":"Picking this carries the first-order half-life across. t½ = {{frac:0.693|k}} holds only when the rate depends on concentration. Options a and b contradict each other, so a select-all can never key both."},{"t":"The rate equation is dC/dt = −kC.","why":"dC/dt = −kC makes the rate k times the concentration, so the rate depends on concentration: first order, the opposite of the process in the stem."},{"t":"The rate equation is dC/dt = −k.","correct":true,"why":"dC/dt = −k has no concentration term, so the same amount is lost per unit time whatever is present. That is the zero-order rate law the stem describes."}],"teach":[{"h":"The two versions of this item","list":["Rate independent of concentration: zero order, {{frac:dC|dt}} = −k, and t½ = {{frac:C0|2k}} depends on C0.","Rate depends on concentration: first order, {{frac:dC|dt}} = −kC, and t½ = {{frac:0.693|k}} is constant.","Each version keys one half-life option and one rate equation; the two half-life options never go together."]}],"quote":"Our stem says independent of concentration, so you should have picked for this one, A and D.","audit":"The other printed version of Quiz 1 Q1 (STYLE.md, Quiz 1; versions handed out with the stems flipped). Options a-c as read aloud on 26 Aug; d is not read out and is dC/dt = -k by the option list of the version in cq1-1. Key \"A and D\" (transcript 08-26).","cite":"Quiz 1 (26 Aug), other version, question 1; her spoken key, transcript 08-26; Introduction.pdf slides 17 and 19"},{"id":"x3-a-q2-first","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"first","concept":"first-order-rate-depends","skill":"tell","source":"both","dupOf":"cq1-2","stem":"Which of the following is true about a first-order process?","options":[{"t":"The elimination rate is at its highest when the amount of drug in the body is at its highest.","correct":true,"why":"First order means the rate is k times the amount present, dC/dt = −kC, so the most drug gives the fastest loss: the rate is highest at the top of the curve and slows as the amount falls."},{"t":"The elimination rate is at its highest when the amount of drug in the body is at its lowest.","why":"Picking this reverses the proportion. In first order the rate falls as the amount falls, so the lowest amount gives the slowest loss, never the fastest."},{"t":"The elimination rate is independent of the amount of drug in the body.","why":"A rate independent of the amount is zero order, dC/dt = −k. It is the key to the other version of this item, which asked about a zero-order process."},{"t":"The elimination rate increases as a function of time.","why":"Time enters only through the amount already lost. In first order the amount falls with time, so the rate falls with time; no elimination process in this course speeds up as time passes."}],"teach":[{"h":"First order","list":["{{frac:dC|dt}} = −kC: the rate is the rate constant times what is present.","Most drug, fastest loss: the curve is steepest at the start and flattens.","The fraction lost per hour, k, and the half-life stay fixed while the rate falls."]}],"quote":"A, right? The rate is highest at the top of the curve when the concentration is highest, OK.","audit":"The other printed version of Quiz 1 Q2 (first-order stem); options as read aloud on 26 Aug; key A (transcript 08-26).","cite":"Quiz 1 (26 Aug), other version, question 2; her spoken key, transcript 08-26; Introduction.pdf slide 18"},{"id":"x3-a-kpos","tier":"new","exam":1,"module":1,"lecture":"L01","topic":"orders","sub":"first","concept":"first-order-properties","skill":"recall","source":"transcript","stem":"Which of the following is true about the rate constant k of a zero-order or a first-order process?","options":[{"t":"It is never a negative number","correct":true,"why":"The concentration falls, so the slope of the line is negative, and k is the slope with its sign reversed. The minus sign is written into the equations, C = C0 − kt and C = C0e^(−kt), so k itself is always reported as a positive number."},{"t":"It is negative for a falling concentration","why":"Picking this puts the decline into k twice. The fall is already the minus sign in the equation; a negative k there would make the concentration rise. A negative k from two points means they were subtracted in the wrong order."},{"t":"It has units of reciprocal time in both orders","why":"Only the first-order constant is reciprocal time, such as hr⁻¹. A zero-order k is itself a rate, in concentration or amount per unit time, such as mg/mL/hr."},{"t":"It changes with the starting concentration in first order","why":"The first-order k is a fixed fraction per unit time and holds no concentration, which is why the first-order half-life, {{frac:0.693|k}}, is constant. The starting concentration enters the zero-order half-life, {{frac:C0|2k}}, not k."}],"teach":[{"h":"Signs and units of k","list":["Both orders report k as a positive number; the minus sign lives in the equations.","First order: k = {{frac:ln(C1 ÷ C2)|t2 − t1}}, the earlier, larger concentration on top; units of reciprocal time.","Zero order: k = {{frac:C1 − C2|t2 − t1}}, earlier minus later; units of concentration or amount per time."]}],"quote":"our rate constant K, whether we're talking 1st order or zero order, our rate constant is never going to be a negative. It's never gonna be a negative number","audit":"Spoken 19 Aug (transcript 08-19) while deriving C = C0 - kt from the negative slope; the annotated Introduction deck page 20 carries the same note in the student's hand.","cite":"Introduction.pdf slides 17 and 18"},{"id":"x3-c-03","tier":"new","exam":3,"module":8,"lecture":"L12","multi":true,"topic":"nonlin","sub":"kmcp","concept":"nl-thalf-cl-trend","skill":"apply","source":"both","stem":"Which of the following would you expect with an increase in the daily dose of a drug that displays nonlinear pharmacokinetics? (Select all that apply)","options":[{"t":"Increased half-life","correct":true,"why":"t½ = VD({{frac:0.693|Vmax}})(KM + Cp). A larger daily dose gives a higher steady-state level, so KM + Cp grows and the half-life lengthens; VD, Vmax and KM do not move."},{"t":"Decreased half-life","why":"Picking this runs the half-life line backward. Cp is added to KM in the numerator of the half-life line, so a higher level gives a longer half-life, not a shorter one."},{"t":"Increased clearance","why":"Picking this carries the dose into the clearance. ClT = {{frac:Vmax|KM + Cp}} has Cp in the denominator, so a higher level gives a lower clearance. In linear kinetics clearance does not change with dose at all."},{"t":"Decreased clearance","correct":true,"why":"ClT = {{frac:Vmax|KM + Cp}}. A higher dose gives a higher Cp, a larger denominator and a lower clearance; this is why the level rises more than in proportion to the dose."},{"t":"Increased Vmax","why":"Picking this treats Vmax as a property of the dose. Vmax is the maximum elimination rate of the enzyme system, a constant for a given drug in a given patient; it does not change with the dose."},{"t":"Decreased Vmax","why":"Picking this reads saturation as a loss of capacity. The enzyme system still has the same Vmax; what changes with the dose is the level, and with it the half-life and the clearance."}],"teach":[{"h":"A larger dose of a nonlinear drug","list":["Vmax and KM are constants for a given drug in a given patient; the dose does not change them.","A higher daily dose gives a higher Cp, and both lines below contain Cp.","t½ = VD({{frac:0.693|Vmax}})(KM + Cp): rises as Cp rises.","ClT = {{frac:Vmax|KM + Cp}}: falls as Cp rises.","In linear kinetics neither changes with the dose; in nonlinear kinetics both do."]}],"quote":"So, concentration, as concentration increases, what's gonna happen to our clearance? It's gonna decrease.","audit":"Written for this review in the format of her Exam 2 In-Class Review question 6 (six paired increase/decrease options, select all). Keys from slides 17 and 18, Nonlinear-Solutions-2.pdf question 3 and Canvas Quiz 5 question 6 (\"Half-life changes as dose is increased\").","cite":"8 - Nonlinear PK.pdf, slides 6 \"Saturation Kinetics\", 17 \"Dependence of Elimination Half-Life on Dose\" and 18 \"Dependence of Clearance on Dose\"; Exam 2 In-Class Review, question 6 (format); transcript 10-14"},{"id":"x3-c-08","tier":"new","exam":3,"module":9,"lecture":"L11","multi":true,"topic":"pkpd","sub":"teff","concept":"dose-double-teff","skill":"apply","source":"both","stem":"Which of the following would you expect with a 2-fold increase in the IV bolus dose of a drug that displays linear, first-order pharmacokinetics? (Select all that apply)","options":[{"t":"The AUC doubles","correct":true,"why":"AUC = {{frac:D0|Cl}} for an IV bolus, and in linear kinetics clearance does not change with the dose, so twice the dose gives twice the area under the curve."},{"t":"The initial plasma concentration doubles","correct":true,"why":"C0 = {{frac:D0|VD}}. The volume of distribution does not change with the dose, so twice the dose gives twice the concentration just after the bolus."},{"t":"The duration of action doubles","why":"Picking this treats the duration as proportional to the dose. In teff = 1.44 t½ ln({{frac:D0|VD × MEC}}) the dose sits inside the logarithm, so doubling it adds one half-life instead."},{"t":"The duration of action increases by one half-life","correct":true,"why":"Doubling C0 adds ln 2 to ln C0, and ln 2 divided by k is one half-life: the level needs exactly one half-life to fall from 2C0 back to C0, then follows the old curve."},{"t":"The half-life doubles","why":"Picking this moves the half-life with the dose. In linear, first-order kinetics t½ = {{frac:0.693|k}} and k does not depend on the dose; a half-life that changes with dose marks a nonlinear drug."},{"t":"The clearance doubles","why":"Picking this moves clearance with the dose. Clearance belongs to the drug and the patient; doubling the dose doubles the AUC instead, so that Cl = {{frac:D0|AUC}} stays the same."}],"teach":[{"h":"Doubling an IV bolus dose, linear kinetics","list":["Doubles: C0 = {{frac:D0|VD}} and AUC = {{frac:D0|Cl}}, because VD and Cl do not change with the dose.","Unchanged: k, t½, VD and Cl.","Duration of action: one half-life longer, not doubled, because the dose sits inside the logarithm in teff = 1.44 t½ ln({{frac:D0|VD × MEC}})."]}],"quote":"Because we expect for our linear pharmacokinetics, a proportional increase, decrease, or whatever, change. In the AUC as well as the concentration as we change the dose.","audit":"Written for this review in the format of her Exam 2 In-Class Review question 6 (select all, increase in dose). Keys: PollEv on slide 12 (doubling does not double duration: False), Quiz 5 question 2 (increased by one half-life), transcript 09-30 (AUC and concentration proportional to dose), IV-Bolus-Practice-4 (doubled dose: no change in half-life or clearance, initial concentration doubled).","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\" and 12 (PollEv); Exam 2 In-Class Review, question 6 (format); 7a---Bioavailability-and-Bioequivalence.pdf, slide \"Absolute Bioavailability\" (Div = Cl × AUCiv); transcript 09-30"},{"id":"x3-c-13","tier":"new","exam":2,"module":7,"lecture":"L10","multi":true,"topic":"bioavail","sub":"factors","concept":"factors-list","skill":"recall","source":"both","stem":"Which of the following can influence the bioavailability of a drug? (Select all that apply)","options":[{"t":"Food effects","correct":true,"why":"Food effects are one of the factors influencing bioavailability, with the physicochemical properties of the drug and formulation, stability and pH effects, first-pass metabolism, prodrugs, drug–drug interactions, efflux transporters, age and disease state."},{"t":"Efflux transporters","correct":true,"why":"Efflux transporters are on the same list of factors influencing bioavailability: the rate and extent to which the active ingredient is absorbed from the product and becomes available at the site of action."},{"t":"Drug–drug interactions","correct":true,"why":"Drug–drug interactions are on the list of factors influencing bioavailability, with food effects and efflux transporters."},{"t":"The apparent volume of distribution","why":"Picking this takes a distribution parameter for a determinant of absorption. VD relates the amount in the body to the plasma level after the drug is in the circulation; it does not decide how much of a dose gets there."},{"t":"The dosing interval","why":"Picking this takes a regimen setting for a property of the product or the patient. The dosing interval changes steady-state levels, but the fraction of each dose that reaches the circulation stays the same."}],"teach":[{"h":"Factors influencing bioavailability","list":["Physicochemical properties of the drug and formulation; drug stability and pH effects; pre-systemic and first-pass metabolism; prodrugs.","Food effects; drug–drug interactions; efflux transporters; age; disease state.","Formulation factors and the first-pass effect are the reasons most often behind low bioavailability.","The volume of distribution, the half-life and the dosing interval do not change F, the fraction of the dose that reaches the circulation."]}],"quote":"we had a long list of factors that can affect bioavailability","audit":"Written for this review from her slide \"Factors Influencing Bioavailability\" (nine bullets); her 10-05 review of Exam 2 objectives named the list. m7-c09 tests one factor with a single answer.","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Factors Influencing Bioavailability\" and \"Summary\"; transcript 10-05"}],"topics":[{"id":"intro","name":"What pharmacokinetics is","open":true,"cite":"Introduction.pdf slides 2–15","subs":[{"id":"disc","name":"Pharmacokinetics and the related disciplines","cite":"Introduction.pdf slides 3–8"},{"id":"terms","name":"ADME and the fundamental terms","cite":"Introduction.pdf slides 4–5"},{"id":"matrix","name":"Whole blood, serum and plasma","cite":"Introduction.pdf slide 10"},{"id":"models","name":"Pharmacokinetic models","cite":"Introduction.pdf slides 11–14"},{"id":"curve","name":"The concentration versus time curve","cite":"Introduction.pdf slide 9"}]},{"id":"orders","name":"Kinetic orders and the maths","open":true,"cite":"Introduction.pdf slides 16–21","subs":[{"id":"zero","name":"Zero-order reactions","cite":"Introduction.pdf slide 17"},{"id":"first","name":"First-order reactions","cite":"Introduction.pdf slide 18"},{"id":"half","name":"Half-life, both orders","cite":"Introduction.pdf slide 19"},{"id":"plots","name":"Linear and semi-logarithmic plots","cite":"Introduction.pdf slides 20–21"},{"id":"decide","name":"Deciding the order from a data set","cite":"Introduction.pdf slides 17–18"}]},{"id":"infusion","name":"Intravenous infusion","cite":"3IntravenousInfusions.pdf, slide \"Objectives\"","subs":[{"id":"basics","name":"What an infusion does, and why the input is zero order","cite":"3IntravenousInfusions.pdf, slide \"Intravenous Infusion\""},{"id":"css","name":"Steady state and continuous dosing","cite":"3IntravenousInfusions.pdf, slide \"Drug Concentration at Steady-State\""},{"id":"pre","name":"Concentration before steady state is reached","cite":"3IntravenousInfusions.pdf, slides \"Drug Concentration Prior to Reaching Steady-State\""},{"id":"rate","name":"Infusion rate for a target steady-state concentration","cite":"3IntravenousInfusions.pdf, slide \"Objectives\", bullet 6"},{"id":"time","name":"Time to reach a stated fraction of steady state","cite":"3IntravenousInfusions.pdf, slide \"Example 4\""},{"id":"stop","name":"Concentration after the infusion is stopped","cite":"3IntravenousInfusions.pdf, slide \"Drug Concentration after an IV Infusion has Ended\""},{"id":"load","name":"Loading dose, alone and with a continuous infusion","cite":"3IntravenousInfusions.pdf, slides \"IV Bolus Loading Dose and Continuous IV Infusion\""}]},{"id":"oral","name":"Oral absorption, single dose","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf slide 2","subs":[{"id":"extravasc","name":"Kinetics after extravascular administration","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf slide 2, bullet 1"},{"id":"conc","name":"Plasma concentration after a single oral dose","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf slide 2, bullet 2"},{"id":"peak","name":"Peak concentration and time to peak","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf slide 2, bullet 3"},{"id":"changes","name":"Effects of changing ka, k and dose","cite":"5---Pharmacokinetics-of-Oral-Absorption.pdf slide 2, bullet 4"}]},{"id":"multi","name":"Multiple dosing: repeated IV bolus (deck 6)","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Objectives\"","subs":[{"id":"accum","name":"Drug accumulation and steady state","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Drug accumulation with repeated administration\""},{"id":"superpos","name":"The principle of superposition","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Superposition\""},{"id":"ssbolus","name":"Maximum, minimum and average at steady state","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Amount of Drug in the Body Following Repeated IV Bolus Injections\" to \"Example 1\""},{"id":"ndose","name":"Concentration after n doses and after the last dose","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Plasma Drug Concentration at Any Time After n Doses\" to \"Example 3\""}]},{"id":"intermit","name":"Multiple dosing: intermittent IV infusions (deck 6)","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slide \"Intermittent Intravenous Infusions\"","subs":[{"id":"why","name":"Why, and the equation for one infusion","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Rationale\" and \"Administering One or More Doses by IV Infusion\""},{"id":"add","name":"Adding the infusions on a time line","cite":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf, slides \"Example 4\" to \"Summary\""}]},{"id":"multoral","name":"Multiple dosing: oral doses (deck 6a)","cite":"6a---Multiple-Oral-Doses.pdf, slide \"Objectives\"","subs":[{"id":"oeq","name":"The multiple-oral-dose equations","cite":"6a---Multiple-Oral-Doses.pdf, slides \"Concentration of Drug in the Plasma at Any Time\" and \"Peak, Trough and Average Plasma Concentrations at Steady State\""},{"id":"ossc","name":"Peak, trough and time to peak at steady state","cite":"6a---Multiple-Oral-Doses.pdf, slides \"Time to Peak at Steady State\" and \"Example 1\""},{"id":"oparam","name":"Changing the dose and the dosing interval","cite":"6a---Multiple-Oral-Doses.pdf, slides \"Multiple-Dosage Regimens\" to \"Consider Peak and Trough\""}]},{"id":"bioavail","name":"Bioavailability and bioequivalence","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Objectives\"","subs":[{"id":"defs","name":"Drug product performance, bioavailability, absolute and relative, bioequivalence","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Drug Product Performance\" to \"Bioequivalence\""},{"id":"factors","name":"Factors influencing bioavailability","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Factors Influencing Bioavailability\" and \"Summary\""},{"id":"fabs","name":"Absolute bioavailability and the equivalent oral dose","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Absolute Bioavailability\" and \"Practice Problem\""},{"id":"frel","name":"Relative bioavailability","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slides \"Relative Bioavailability\" and \"Practice Problem\""},{"id":"figure","name":"Reading the bioequivalence example","cite":"7a---Bioavailability-and-Bioequivalence.pdf, slide \"Bioequivalence Example\""}]},{"id":"pkpd","name":"PK-PD relationship","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 2 \"Objectives\"","subs":[{"id":"pd","name":"Pharmacodynamics and the exposure–response relationship","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 3 \"Pharmacodynamics\""},{"id":"doseresp","name":"Response rising with dose and concentration up to a maximum","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 4 \"Relationship of Dose to Pharmacologic Effect\", 5 \"Typical Log Dose-versus-Pharmacologic Response Curves\" and 11 \"Summary\""},{"id":"teff","name":"Dose and the duration of activity, teff","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 6 to 9 and 12"},{"id":"dosefor","name":"The dose for a target duration of activity","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slide 8 and the In-Class Activity on slide 13"},{"id":"thalf","name":"Elimination half-life and the duration of activity","cite":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf, slides 9 \"Effect of Dose and Elimination Half-life on Duration of Activity\" and 10 \"Effect of Elimination Half-life on Duration of Activity\""}]},{"id":"nonlin","name":"Nonlinear pharmacokinetics","cite":"8 - Nonlinear PK.pdf, slide 2 \"Objectives\"","subs":[{"id":"linear","name":"Linear and nonlinear pharmacokinetics; saturation kinetics","cite":"8 - Nonlinear PK.pdf, slides 3 \"Linear vs. Nonlinear Pharmacokinetics\" to 6 \"Saturation Kinetics\", and 19 \"Summary\""},{"id":"kmcp","name":"KM and Cp: the order of saturable elimination, half-life and clearance","cite":"8 - Nonlinear PK.pdf, slides 7 \"Parameters\", 8 \"Saturable-Enzymatic Elimination Processes\", 9, 17 and 18"},{"id":"kmvmax","name":"Vmax and KM from two dose rates in a patient","cite":"8 - Nonlinear PK.pdf, slides 13 \"Determination of KM and Vmax by Direct Method\", 14 \"Example\" and 15"},{"id":"dose","name":"Dose rate and steady state for a nonlinear drug such as phenytoin","cite":"8 - Nonlinear PK.pdf, slides 11 \"In Vivo Determination of KM and Vmax\" and 12 \"Example\""}]}],"lectures":[{"id":"L01","deck":"Introduction.pdf","label":"Module 1: Introduction, kinetic orders and AUC (17 & 19 Aug)","exam":1,"module":1},{"id":"L04","deck":"3IntravenousInfusions.pdf","label":"Module 3: Intravenous infusion (2 Sep)","exam":1,"module":3},{"id":"L06","deck":"5---Pharmacokinetics-of-Oral-Absorption.pdf","label":"Module 5: Pharmacokinetics of oral absorption (16 & 21 Sep)","exam":2,"module":5},{"id":"L07","deck":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf","label":"Module 6: Repetitive IV bolus injections (23 Sep)","exam":2,"module":6},{"id":"L08","deck":"6---Repetitive-IV-Bolus-and-Intermittent-IV-Infusions.pdf","label":"Module 6: Intermittent IV infusions (28 Sep)","exam":2,"module":6},{"id":"L09","deck":"6a---Multiple-Oral-Doses.pdf","label":"Module 6a: Multiple oral doses (28 Sep)","exam":2,"module":6},{"id":"L10","deck":"7a---Bioavailability-and-Bioequivalence.pdf","label":"Module 7a: Bioavailability and bioequivalence (30 Sep)","exam":2,"module":7},{"id":"L11","deck":"7b---Pharmacokinetics-and-Pharmacodynamics.pdf","label":"Module 7b: PK-PD relationship (12 Oct)","exam":3,"module":9},{"id":"L12","deck":"8 - Nonlinear PK.pdf","label":"Module 8: Nonlinear pharmacokinetics (14 Oct)","exam":3,"module":8}],"skills":[{"id":"recall","label":"Recall a definition or fact","short":"Recall","kind":"concept"},{"id":"tell","label":"Tell two similar things apart","short":"Tell apart","kind":"concept"},{"id":"read","label":"Read a graph, table or equation","short":"Read","kind":"concept"},{"id":"apply","label":"Reason about a patient or a change","short":"Apply","kind":"concept"},{"id":"order","label":"Decide the order from a data set","short":"Order","kind":"calc"},{"id":"infusion","label":"Infusion rate and steady state","short":"Infusion","kind":"calc"},{"id":"multidose","label":"Repeated dosing — peak, trough, average","short":"Multi-dose","kind":"calc"},{"id":"bioavail","label":"Bioavailability — absolute, relative, equivalent dose","short":"Bioavail","kind":"calc"}],"images":{"ord_linear_straight":"data:image/svg+xml;base64,","ord_semilog_curve":"data:image/svg+xml;base64,","ord_semilog_straight":"data:image/svg+xml;base64,","slide_Introduction_p20":"data:image/webp;base64,","slide_Introduction_p23":"data:image/webp;base64,","slide_Introduction_p24":"data:image/webp;base64,","slide_Introduction_p6":"data:image/webp;base64,"}};
const PRE = 'sw-', FILE = 'q90_stopwatch_pk.js';
const pre = id => PRE + id;
/* prof: the course's first professor. have: what the course already holds of other modules' data,
   {eq: EQUATIONS ids, asks: ASKS keys} (none when left out). */
function courseData(prof, have){
  if(typeof prof !== 'string' || !prof || /['\\\n]/.test(prof)) throw new Error('the professor cannot be written as a literal');
  const EQ = new Set((have && have.eq) || []), ASK = new Set((have && have.asks) || []), left = {setup: [], asks: []};
  const setupOk = st => !!st && (st.eq === 'none' || EQ.has(st.eq)) && (st.pre || []).every(id => EQ.has(id));
  const lit = s => { if(!/^[A-Za-z0-9_. -]+$/.test(String(s))) throw new Error('cannot be written as a literal: ' + s); return "'" + s + "'"; };
  const qline = q => { const c = Object.assign({}, q); ['id', 'type', 'dupOf', 'skill'].forEach(k => { delete c[k]; });
    if(c.topic) c.topic = pre(c.topic); if(c.sub) c.sub = pre(c.sub); if(c.lecture) c.lecture = pre(c.lecture);
    if(c.setup !== undefined && !setupOk(c.setup)){ delete c.setup; left.setup.push(pre(q.id)); }
    if(c.asks !== undefined && !ASK.has(c.asks)){ delete c.asks; left.asks.push(pre(q.id)); }
    return '{id:' + lit(pre(q.id)) + ',' + (q.type ? ' type:' + lit(q.type) + ',' : '') + (q.dupOf ? ' dupOf:' + lit(pre(q.dupOf)) + ',' : '') +
      ' skill:' + lit(q.skill) + ', prof:' + lit(prof) + ', ' + JSON.stringify(c).slice(1) + ','; };
  const qlines = FIX.qs.map(qline);             // first, so `left` is filled for the file's header
  const text = '/* stopwatch: Basic-Pharmacokinetics\' own topics and questions (ac2eb73), as\n' +
    '   features/stopwatch/current/test_fixture.js names them; question, topic, subtopic and lecture ids prefixed sw-,\n' +
    '   the professor set to the course\'s own' + (left.setup.length ? '; setup left out of ' + left.setup.join(', ') + ' (equations the course lacks)' : '') +
    (left.asks.length ? '; asks left out of ' + left.asks.join(', ') + ' (keys the course\'s ASKS lacks)' : '') + ' */\n' +
    'TOPICS.push(\n' + FIX.topics.map(t => JSON.stringify(Object.assign({}, t, {id: pre(t.id), subs: (t.subs || []).map(x => Object.assign({}, x, {id: pre(x.id)})), prof}))).join(',\n') + ');\n' +
    'QUESTIONS.push(\n' + qlines.join('\n') + '\n);\n';
  // a lecture as {id:'sw-L01', ...}: state_check.js finds a lecture by its id:'...' entry in course.js
  const lecture = l => { const c = Object.assign({}, l); delete c.id; c.prof = prof; return '{id:' + lit(pre(l.id)) + ', ' + JSON.stringify(c).slice(1); };
  const courseLine = 'COURSE.lectures = (COURSE.lectures || []).concat([' + FIX.lectures.map(lecture).join(', ') + ']); ' +
    'COURSE.skills = (COURSE.skills || []).concat(' + JSON.stringify(FIX.skills) + '.filter(s => !(COURSE.skills || []).some(k => k.id === s.id))); ' +
    'COURSE.exams = [' + JSON.stringify(FIX.exam) + ']; COURSE.activeExam = ' + JSON.stringify(FIX.activeExam) + ';';
  return {files: {[FILE]: text}, courseLine, left};
}
/* The course's images.json with the fixture's images added (an image the course already
   has under the same key with other data stops it: nothing of the course is overwritten). */
function withImages(json){
  const have = JSON.parse(json || '{}');
  for(const [k, v] of Object.entries(FIX.images)){
    if(k in have && have[k] !== v) throw new Error('images.json already has another image under ' + k);
    have[k] = v;
  }
  return JSON.stringify(have, null, 1) + '\n';
}
module.exports = {FIX, PRE, FILE, pre, courseData, withImages};
